-- Regulation Center for the Student Council
-- Source: Google Doc revision captured from the school's working regulation draft.
-- This migration seeds the document as draft/advisory; it does not make the regulation effective.

begin;

create table if not exists public.council_regulation_versions (
  id bigint generated always as identity primary key,
  regulation_key text not null,
  version_label text not null,
  title text not null,
  status text not null default 'draft' check (status in ('draft','pending_approval','approved','effective','superseded','archived')),
  implementation_mode text not null default 'advisory' check (implementation_mode in ('advisory','enforced')),
  source_document_url text,
  source_revision_id text,
  effective_date date,
  approved_at timestamptz,
  approved_by_profile_id uuid references public.profiles(id) on delete set null,
  superseded_by bigint references public.council_regulation_versions(id) on delete set null,
  created_by_profile_id uuid references public.profiles(id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (regulation_key, version_label)
);

create table if not exists public.council_regulation_sections (
  id bigint generated always as identity primary key,
  version_id bigint not null references public.council_regulation_versions(id) on delete cascade,
  section_no integer not null,
  title text not null,
  sort_order integer not null default 0,
  unique (version_id, section_no)
);

create table if not exists public.council_regulation_clauses (
  id bigint generated always as identity primary key,
  version_id bigint not null references public.council_regulation_versions(id) on delete cascade,
  section_id bigint not null references public.council_regulation_sections(id) on delete restrict,
  clause_no integer not null,
  title text not null default '',
  body text not null,
  keywords text[] not null default '{}',
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  unique (version_id, clause_no)
);

create table if not exists public.council_regulation_audit_logs (
  id bigint generated always as identity primary key,
  version_id bigint references public.council_regulation_versions(id) on delete set null,
  clause_id bigint references public.council_regulation_clauses(id) on delete set null,
  actor_profile_id uuid references public.profiles(id) on delete set null,
  actor_role text,
  action text not null,
  before_data jsonb,
  after_data jsonb,
  reason text,
  created_at timestamptz not null default now()
);

alter table public.council_regulation_versions enable row level security;
alter table public.council_regulation_sections enable row level security;
alter table public.council_regulation_clauses enable row level security;
alter table public.council_regulation_audit_logs enable row level security;

drop policy if exists council_regulation_versions_read on public.council_regulation_versions;
create policy council_regulation_versions_read on public.council_regulation_versions for select to authenticated using (status <> 'archived');
drop policy if exists council_regulation_sections_read on public.council_regulation_sections;
create policy council_regulation_sections_read on public.council_regulation_sections for select to authenticated using (
  exists (select 1 from public.council_regulation_versions v where v.id = version_id and v.status <> 'archived')
);
drop policy if exists council_regulation_clauses_read on public.council_regulation_clauses;
create policy council_regulation_clauses_read on public.council_regulation_clauses for select to authenticated using (
  exists (select 1 from public.council_regulation_versions v where v.id = version_id and v.status <> 'archived')
);
drop policy if exists council_regulation_audit_logs_admin_read on public.council_regulation_audit_logs;
create policy council_regulation_audit_logs_admin_read on public.council_regulation_audit_logs for select to authenticated using (
  get_user_role() = 'admin' or exists (select 1 from public.profiles where id = auth.uid() and is_also_admin = true)
);

create index if not exists council_regulation_sections_version_order_idx on public.council_regulation_sections (version_id, sort_order);
create index if not exists council_regulation_clauses_version_order_idx on public.council_regulation_clauses (version_id, sort_order);
create index if not exists council_regulation_clauses_section_order_idx on public.council_regulation_clauses (section_id, sort_order);
create index if not exists council_regulation_audit_logs_clause_created_idx on public.council_regulation_audit_logs (clause_id, created_at desc);

create or replace function public.update_council_regulation_clause(p_clause_id bigint, p_title text, p_body text, p_keywords text[] default '{}')
returns public.council_regulation_clauses language plpgsql security definer set search_path = public
as $$
declare
  v_old public.council_regulation_clauses%rowtype;
  v_new public.council_regulation_clauses%rowtype;
  v_actor uuid := auth.uid();
  v_status text;
begin
  if not (get_user_role() = 'admin' or exists (select 1 from public.profiles where id = v_actor and is_also_admin = true)) then raise exception 'permission denied'; end if;
  select * into v_old from public.council_regulation_clauses where id = p_clause_id for update;
  if not found then raise exception 'regulation clause not found'; end if;
  select status into v_status from public.council_regulation_versions where id = v_old.version_id;
  if v_status is null or v_status not in ('draft','pending_approval') then raise exception 'only a working draft can be edited'; end if;
  if nullif(trim(p_body), '') is null then raise exception 'clause body is required'; end if;
  update public.council_regulation_clauses set title = coalesce(nullif(trim(p_title), ''), title), body = trim(p_body), keywords = coalesce(p_keywords, '{}'), updated_at = now() where id = p_clause_id returning * into v_new;
  insert into public.council_regulation_audit_logs (version_id, clause_id, actor_profile_id, actor_role, action, before_data, after_data) values (v_new.version_id, v_new.id, v_actor, get_user_role(), 'update_clause', to_jsonb(v_old), to_jsonb(v_new));
  return v_new;
end;
$$;

create or replace function public.create_council_regulation_clause(p_version_id bigint, p_section_id bigint, p_clause_no integer, p_title text, p_body text, p_keywords text[] default '{}')
returns public.council_regulation_clauses language plpgsql security definer set search_path = public
as $$
declare
  v_new public.council_regulation_clauses%rowtype;
  v_actor uuid := auth.uid();
  v_status text;
begin
  if not (get_user_role() = 'admin' or exists (select 1 from public.profiles where id = v_actor and is_also_admin = true)) then raise exception 'permission denied'; end if;
  select status into v_status from public.council_regulation_versions where id = p_version_id;
  if v_status is null or v_status not in ('draft','pending_approval') then raise exception 'only a working draft can be edited'; end if;
  if nullif(trim(p_body), '') is null then raise exception 'clause body is required'; end if;
  insert into public.council_regulation_clauses (version_id, section_id, clause_no, title, body, keywords, sort_order) values (p_version_id, p_section_id, p_clause_no, coalesce(nullif(trim(p_title), ''), ''), trim(p_body), coalesce(p_keywords, '{}'), p_clause_no) returning * into v_new;
  insert into public.council_regulation_audit_logs (version_id, clause_id, actor_profile_id, actor_role, action, after_data) values (v_new.version_id, v_new.id, v_actor, get_user_role(), 'create_clause', to_jsonb(v_new));
  return v_new;
end;
$$;

revoke all on function public.update_council_regulation_clause(bigint, text, text, text[]) from public, anon, authenticated;
grant execute on function public.update_council_regulation_clause(bigint, text, text, text[]) to authenticated;
revoke all on function public.create_council_regulation_clause(bigint, bigint, integer, text, text, text[]) from public, anon, authenticated;
grant execute on function public.create_council_regulation_clause(bigint, bigint, integer, text, text, text[]) to authenticated;

insert into public.council_regulation_versions (regulation_key, version_label, title, status, implementation_mode, source_document_url, source_revision_id)
values ('azizstan_student_council', '2569', 'ระเบียบโรงเรียนมูลนิธิอาซิซสถาน ว่าด้วยสภานักเรียน พ.ศ. ๒๕๖๙', 'draft', 'advisory',
  'https://docs.google.com/document/d/1lX7v3BkGBID-xRBDB0MFDDqPvT5YAVmaF540MUGY7RI/edit',
  'ANLCKQm6Pz0eABJxfIeNRptnjq2PJRjyn2YGuxZfh27PdN6p8kxMYuWZiP6ZH1D9Gq1N21yDgv6Pd_CXxXm2_tNEuEoVu14Dfe2Z0_DcfmU')
on conflict (regulation_key, version_label) do nothing;

with v as (select id from public.council_regulation_versions where regulation_key = 'azizstan_student_council' and version_label = '2569')
insert into public.council_regulation_sections (version_id, section_no, title, sort_order)
select v.id, x.section_no, x.title, x.sort_order from v cross join jsonb_to_recordset('[{"section_no":1,"title":"บททั่วไป","sort_order":1},{"section_no":2,"title":"วัตถุประสงค์ของสภานักเรียน","sort_order":2},{"section_no":3,"title":"องค์ประกอบและโครงสร้างสภานักเรียน","sort_order":3},{"section_no":4,"title":"คุณสมบัติผู้สมัครสภานักเรียน","sort_order":4},{"section_no":5,"title":"การได้มาซึ่งคณะกรรมการสภานักเรียน","sort_order":5},{"section_no":6,"title":"วาระ การพ้นจากตำแหน่ง และตำแหน่งว่าง","sort_order":6},{"section_no":7,"title":"วินัย มาตรฐานความประพฤติ และการพิจารณาพ้นจากสมาชิกสภานักเรียน","sort_order":7},{"section_no":8,"title":"อำนาจและหน้าที่ของสภานักเรียน","sort_order":8},{"section_no":9,"title":"หน้าที่ของตำแหน่งสำคัญและฝ่ายต่าง ๆ","sort_order":9},{"section_no":10,"title":"การประชุมและการลงมติ","sort_order":10},{"section_no":11,"title":"กิจกรรมและการพัฒนาศักยภาพสภานักเรียน","sort_order":11},{"section_no":12,"title":"แผนงาน โครงการ การเงิน เงินสำรอง เงินออม และทรัพย์สิน","sort_order":12},{"section_no":13,"title":"ครูที่ปรึกษาสภานักเรียนและการกำกับดูแล","sort_order":13},{"section_no":14,"title":"เอกสาร ข้อมูล การประชาสัมพันธ์ และความโปร่งใส","sort_order":14},{"section_no":15,"title":"การประเมินการปฏิบัติหน้าที่ การเข้าร่วม และการรับรองผลการปฏิบัติหน้าที่","sort_order":15},{"section_no":16,"title":"การส่งมอบงาน การแก้ไขระเบียบ และบทเฉพาะกาล","sort_order":16}]'::jsonb) as x(section_no integer, title text, sort_order integer)
on conflict (version_id, section_no) do nothing;

with v as (select id from public.council_regulation_versions where regulation_key = 'azizstan_student_council' and version_label = '2569')
insert into public.council_regulation_clauses (version_id, section_id, clause_no, title, body, keywords, sort_order)
select v.id, s.id, x.clause_no, x.title, x.body, array(select jsonb_array_elements_text(x.keywords)), x.sort_order
from v join public.council_regulation_sections s on s.version_id = v.id
join jsonb_to_recordset('[{"section_no":1,"clause_no":1,"title":"ระเบียบนี้เรียกว่า “ระเบียบโรงเรียนมูลนิธิอาซิซสถาน ว่าด้วยสภานักเรียน พ.ศ. ๒๕๖๙”","body":"ระเบียบนี้เรียกว่า “ระเบียบโรงเรียนมูลนิธิอาซิซสถาน ว่าด้วยสภานักเรียน พ.ศ. ๒๕๖๙”","keywords":["หมวด 1"],"sort_order":1},{"section_no":1,"clause_no":2,"title":"ระเบียบนี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศเป็นต้นไป","body":"ระเบียบนี้ให้ใช้บังคับตั้งแต่วันถัดจากวันประกาศเป็นต้นไป","keywords":["หมวด 1"],"sort_order":2},{"section_no":1,"clause_no":3,"title":"ในระเบียบนี้ คำต่อไปนี้มีความหมายดังนี้","body":"ในระเบียบนี้ คำต่อไปนี้มีความหมายดังนี้\n(๑) “โรงเรียน” หมายความว่า โรงเรียนมูลนิธิอาซิซสถาน\n(๒) “ผู้บริหารโรงเรียน” หมายความว่า ผู้อำนวยการโรงเรียน หรือผู้ที่ได้รับมอบหมายให้ปฏิบัติหน้าที่แทน\n(๓) “ฝ่ายปกครอง” หมายความว่า หน่วยงานภายในโรงเรียนที่รับผิดชอบงานด้านการดูแลช่วยเหลือนักเรียน ระเบียบวินัย และงานอื่นตามโครงสร้างการบริหารของโรงเรียน\n(๔) “งานกิจกรรมนักเรียน” หมายความว่า งานภายใต้ฝ่ายปกครองซึ่งรับผิดชอบการส่งเสริม สนับสนุน และกำกับกิจกรรมของนักเรียน รวมถึงกิจการสภานักเรียน\n(๕) “สภานักเรียน” หมายความว่า องค์กรของนักเรียนโรงเรียนมูลนิธิอาซิซสถานซึ่งจัดตั้งขึ้นตามระเบียบนี้\n(๖) “คณะกรรมการสภานักเรียน” หมายความว่า นักเรียนที่ผ่านกระบวนการสรรหา คัดเลือก เลือกตั้ง และได้รับการแต่งตั้งตามระเบียบนี้\n(๗) “ครูที่ปรึกษาสภานักเรียน” หมายความว่า ครูหรือบุคลากรทางการศึกษาที่โรงเรียนแต่งตั้งให้ทำหน้าที่ให้คำปรึกษา สนับสนุน กำกับ และประสานงานสภานักเรียนตามฝ่ายที่ได้รับมอบหมาย\n(๘) “หัวหน้าคณะครูที่ปรึกษาสภานักเรียน” หมายความว่า หัวหน้าฝ่ายปกครอง ซึ่งทำหน้าที่กำกับ ดูแล และเป็นหัวหน้าของครูที่ปรึกษาสภานักเรียน\n(๙) “YLA” หมายความว่า กิจกรรมเสริมทักษะภาวะผู้นำ Youth Leadership For Azizstan ซึ่งใช้เป็นส่วนหนึ่งของกระบวนการพัฒนาและสรรหาคณะกรรมการสภานักเรียน\n(๑๐) “ค่าผ้าชุดสภานักเรียน” หมายความว่า ค่าใช้จ่ายสำหรับจัดซื้อผ้าที่ใช้ในการตัดชุดสภานักเรียนในแต่ละวาระ ตามแบบและหลักเกณฑ์ที่โรงเรียนกำหนด\n(๑๑) “เงินสำรองค่าใช้จ่ายในการปฏิบัติหน้าที่สภานักเรียน” หมายความว่า เงินจำนวน ๕๐๐ บาทที่สมาชิกสภานักเรียนแต่ละคนวางไว้เป็นเงินสำรองสำหรับภาระค่าใช้จ่ายที่ได้รับอนุมัติและค้างชำระ โดยเงินดังกล่าวยังเป็นสิทธิของสมาชิกตามเงื่อนไขในระเบียบนี้\n(๑๒) “เงินออมสภานักเรียน” หมายความว่า เงินที่สมาชิกสภานักเรียนสะสมเป็นรายบุคคลตามระบบออมของสภานักเรียน เพื่อเตรียมค่าใช้จ่ายสำหรับกิจกรรมปลายวาระหรือกิจกรรมอื่นที่โรงเรียนกำหนด โดยมิใช่เงินรายได้ส่วนกลางของสภานักเรียน\n(๑๓) “บัตรประจำตัวสภานักเรียน” หมายความว่า บัตรที่โรงเรียนจัดทำหรือรับรองเพื่อแสดงสถานะ ตำแหน่ง หรือฝ่ายของสมาชิกสภานักเรียนในวาระนั้น ซึ่งใช้เพื่อการระบุตัวตนและการปฏิบัติหน้าที่ตามที่ได้รับมอบหมายเท่านั้น","keywords":["หมวด 1"],"sort_order":3},{"section_no":1,"clause_no":4,"title":"สภานักเรียนอยู่ภายใต้งานกิจกรรมนักเรียน ฝ่ายปกครอง โดยมีหัวหน้าฝ่ายปกครองเป็นหัวหน้าคณะครูที่ปรึกษาสภานักเรียน และมีครูที่ปรึกษาสภานักเรียนรับผิดชอบกำกับดูแลตามฝ่ายหรือภารกิจที่...","body":"สภานักเรียนอยู่ภายใต้งานกิจกรรมนักเรียน ฝ่ายปกครอง โดยมีหัวหน้าฝ่ายปกครองเป็นหัวหน้าคณะครูที่ปรึกษาสภานักเรียน และมีครูที่ปรึกษาสภานักเรียนรับผิดชอบกำกับดูแลตามฝ่ายหรือภารกิจที่ได้รับมอบหมาย","keywords":["หมวด 1"],"sort_order":4},{"section_no":1,"clause_no":5,"title":"สภานักเรียนเป็นองค์กรของนักเรียนภายใต้การกำกับดูแลของโรงเรียน มิใช่นิติบุคคล และไม่มีอำนาจผูกพันโรงเรียนกับบุคคลภายนอก เว้นแต่ได้รับอนุญาตหรือมอบหมายจากผู้บริหารโรงเรียน","body":"สภานักเรียนเป็นองค์กรของนักเรียนภายใต้การกำกับดูแลของโรงเรียน มิใช่นิติบุคคล และไม่มีอำนาจผูกพันโรงเรียนกับบุคคลภายนอก เว้นแต่ได้รับอนุญาตหรือมอบหมายจากผู้บริหารโรงเรียน","keywords":["หมวด 1"],"sort_order":5},{"section_no":1,"clause_no":6,"title":"การดำเนินงานของสภานักเรียนต้องยึดกฎหมาย ระเบียบและนโยบายของโรงเรียน หลักการศาสนาอิสลาม คุณธรรม จริยธรรม ความรับผิดชอบ ความโปร่งใส ประโยชน์ส่วนรวม และการเคารพศักดิ์ศรีของผู้อื่น","body":"การดำเนินงานของสภานักเรียนต้องยึดกฎหมาย ระเบียบและนโยบายของโรงเรียน หลักการศาสนาอิสลาม คุณธรรม จริยธรรม ความรับผิดชอบ ความโปร่งใส ประโยชน์ส่วนรวม และการเคารพศักดิ์ศรีของผู้อื่น\nหมวด ๒\nวัตถุประสงค์ของสภานักเรียน","keywords":["หมวด 1"],"sort_order":6},{"section_no":2,"clause_no":7,"title":"ให้จัดตั้งสภานักเรียนโดยมีวัตถุประสงค์ดังต่อไปนี้","body":"ให้จัดตั้งสภานักเรียนโดยมีวัตถุประสงค์ดังต่อไปนี้\n(๑) ส่งเสริมให้นักเรียนมีภาวะผู้นำ ความรับผิดชอบ ความซื่อสัตย์ และจิตสาธารณะ\n(๒) ส่งเสริมการทำงานเป็นทีม การวางแผน การสื่อสาร การแก้ปัญหา และการตัดสินใจอย่างมีเหตุผล\n(๓) เปิดโอกาสให้นักเรียนมีส่วนร่วมในการพัฒนาโรงเรียนภายในขอบเขตที่เหมาะสม\n(๔) เป็นช่องทางรับฟังความคิดเห็น ข้อเสนอแนะ และความต้องการของนักเรียน\n(๕) ส่งเสริมกิจกรรมที่เป็นประโยชน์ต่อนักเรียน โรงเรียน ชุมชน และสังคม\n(๖) ส่งเสริมระเบียบวินัย คุณธรรม จริยธรรม และการดำเนินชีวิตที่สอดคล้องกับหลักการศาสนาอิสลาม\n(๗) พัฒนาทักษะการบริหารโครงการ การใช้เทคโนโลยี การประชาสัมพันธ์ และการทำงานเพื่อส่วนรวม\n(๘) สร้างระบบถ่ายทอดองค์ความรู้ ประสบการณ์ เอกสาร และทรัพยากรจากสภานักเรียนรุ่นหนึ่งไปยังรุ่นถัดไป\nหมวด ๓\nองค์ประกอบและโครงสร้างสภานักเรียน","keywords":["หมวด 2"],"sort_order":7},{"section_no":3,"clause_no":8,"title":"โรงเรียนให้มีสภานักเรียนหนึ่งองค์กร โดยแบ่งการดำเนินงานเป็นสภานักเรียนชายและสภานักเรียนหญิงตามบริบทของโรงเรียนและหลักการศาสนาอิสลาม ทั้งสองส่วนดำเนินงานแยกกันในด้านการบริหารสมาช...","body":"โรงเรียนให้มีสภานักเรียนหนึ่งองค์กร โดยแบ่งการดำเนินงานเป็นสภานักเรียนชายและสภานักเรียนหญิงตามบริบทของโรงเรียนและหลักการศาสนาอิสลาม ทั้งสองส่วนดำเนินงานแยกกันในด้านการบริหารสมาชิกและภารกิจประจำฝ่าย แต่ให้ประสานและร่วมดำเนินกิจกรรมส่วนรวมภายใต้การกำกับของครูที่ปรึกษาสภานักเรียน","keywords":["หมวด 3"],"sort_order":8},{"section_no":3,"clause_no":9,"title":"สภานักเรียนชายและสภานักเรียนหญิงให้มีโครงสร้างตำแหน่งและฝ่ายเหมือนกัน ประกอบด้วย","body":"สภานักเรียนชายและสภานักเรียนหญิงให้มีโครงสร้างตำแหน่งและฝ่ายเหมือนกัน ประกอบด้วย\n(๑) ประธานสภานักเรียน\n(๒) รองประธานสภานักเรียน\n(๓) เลขานุการ\n(๔) รองเลขานุการ\n(๕) ฝ่ายวิชาการ\n(๖) ฝ่ายปกครอง\n(๗) ฝ่ายอาคารสถานที่\n(๘) ฝ่ายนันทนาการและสวัสดิการ\n(๙) ฝ่ายศาสนสัมพันธ์ (อีบาดัต)\n(๑๐) ฝ่ายประชาสัมพันธ์\n(๑๑) ฝ่ายสื่อสารสัมพันธ์ (ไอที)\n(๑๒) ฝ่ายมวลชนสัมพันธ์\n(๑๓) เหรัญญิก","keywords":["หมวด 3"],"sort_order":9},{"section_no":3,"clause_no":10,"title":"จำนวนสมาชิกของแต่ละฝ่าย การมอบหมายผู้รับผิดชอบ และการจัดสมาชิกลงในแต่ละฝ่าย ให้กำหนดตามความเหมาะสมของแต่ละวาระ โดยคำนึงถึงจำนวนสมาชิก ภารกิจ และศักยภาพของนักเรียน ทั้งนี้ โครงสร...","body":"จำนวนสมาชิกของแต่ละฝ่าย การมอบหมายผู้รับผิดชอบ และการจัดสมาชิกลงในแต่ละฝ่าย ให้กำหนดตามความเหมาะสมของแต่ละวาระ โดยคำนึงถึงจำนวนสมาชิก ภารกิจ และศักยภาพของนักเรียน ทั้งนี้ โครงสร้างของสภานักเรียนชายและสภานักเรียนหญิงให้ใช้ชื่อฝ่ายตามข้อ ๙ เป็นหลัก เว้นแต่โรงเรียนมีคำสั่งหรือประกาศกำหนดเป็นอย่างอื่น","keywords":["หมวด 3"],"sort_order":10},{"section_no":3,"clause_no":11,"title":"สมาชิกสภานักเรียนทุกคนต้องปฏิบัติงานตามตำแหน่งหรือฝ่ายที่ได้รับมอบหมาย และอาจได้รับมอบหมายให้สนับสนุนงานข้ามฝ่าย หรือร่วมปฏิบัติภารกิจกับสภานักเรียนอีกฝ่ายหนึ่งได้เมื่อมีความจำเ...","body":"สมาชิกสภานักเรียนทุกคนต้องปฏิบัติงานตามตำแหน่งหรือฝ่ายที่ได้รับมอบหมาย และอาจได้รับมอบหมายให้สนับสนุนงานข้ามฝ่าย หรือร่วมปฏิบัติภารกิจกับสภานักเรียนอีกฝ่ายหนึ่งได้เมื่อมีความจำเป็นหรือเป็นกิจกรรมส่วนรวมของโรงเรียน\nหมวด ๔\nคุณสมบัติผู้สมัครสภานักเรียน","keywords":["หมวด 3"],"sort_order":11},{"section_no":4,"clause_no":12,"title":"ผู้สมัครเข้ารับการคัดเลือกเป็นสภานักเรียนต้องมีคุณสมบัติดังต่อไปนี้","body":"ผู้สมัครเข้ารับการคัดเลือกเป็นสภานักเรียนต้องมีคุณสมบัติดังต่อไปนี้\n(๑) เป็นนักเรียนระดับชั้นมัธยมศึกษาปีที่ ๓ ถึงมัธยมศึกษาปีที่ ๕ ในภาคเรียนที่เปิดรับสมัคร\n(๒) มีผลการเรียนเฉลี่ยสะสมตั้งแต่ ๒.๐๐ ขึ้นไป โดยผู้ที่มีผลการเรียนเฉลี่ยสะสมตั้งแต่ ๒.๕๐ ขึ้นไปอาจได้รับการพิจารณาเป็นกรณีพิเศษตามหลักเกณฑ์ของคณะกรรมการคัดเลือก\n(๓) มีเกียรติบัตรหรือหลักฐานการเข้าร่วมกิจกรรม การจัดกิจกรรม การบำเพ็ญประโยชน์ หรือกิจกรรมที่แสดงถึงการมีส่วนร่วม ไม่น้อยกว่า ๒ รายการ\n(๔) ได้รับการรับรองความเหมาะสมจากครูที่ปรึกษาสามัญประจำชั้น\n(๕) ได้รับความเห็นหรือการรับรองจากสมาชิกสภานักเรียนวาระปัจจุบันตามรูปแบบที่โรงเรียนกำหนด เพื่อใช้เป็นข้อมูลประกอบการพิจารณาความเหมาะสม ทั้งนี้ ความเห็นหรือการรับรองดังกล่าวไม่ให้ถือเป็นสิทธิยับยั้งผู้สมัครที่มีคุณสมบัติครบถ้วน\n(๖) ส่งวิดีโอแนะนำตนเอง ความยาวไม่น้อยกว่า ๑ นาที โดยอธิบายเหตุผลหรือแรงบันดาลใจในการสมัครเป็นสภานักเรียน และแนวคิดเกี่ยวกับการทำงานเพื่อส่วนรวม\n(๗) มีคะแนนความประพฤติติดลบไม่เกิน ๓๐ คะแนน และไม่มีประวัติการกระทำผิดร้ายแรงที่โรงเรียนเห็นว่าไม่เหมาะสมต่อการดำรงตำแหน่ง","keywords":["หมวด 4"],"sort_order":12},{"section_no":4,"clause_no":13,"title":"ผู้สมัครต้องรับรองว่าข้อมูล เอกสาร และหลักฐานที่ยื่นสมัครเป็นความจริง หากตรวจพบว่ามีการให้ข้อมูลเท็จหรือปกปิดข้อเท็จจริงสำคัญ คณะกรรมการคัดเลือกอาจตัดสิทธิผู้สมัครได้","body":"ผู้สมัครต้องรับรองว่าข้อมูล เอกสาร และหลักฐานที่ยื่นสมัครเป็นความจริง หากตรวจพบว่ามีการให้ข้อมูลเท็จหรือปกปิดข้อเท็จจริงสำคัญ คณะกรรมการคัดเลือกอาจตัดสิทธิผู้สมัครได้","keywords":["หมวด 4"],"sort_order":13},{"section_no":4,"clause_no":14,"title":"โรงเรียนอาจกำหนดหลักเกณฑ์เพิ่มเติมที่จำเป็นสำหรับการรับสมัครในแต่ละวาระได้ โดยต้องประกาศให้ผู้สมัครทราบก่อนปิดรับสมัคร และต้องไม่ขัดกับหลักเกณฑ์หลักตามระเบียบนี้","body":"โรงเรียนอาจกำหนดหลักเกณฑ์เพิ่มเติมที่จำเป็นสำหรับการรับสมัครในแต่ละวาระได้ โดยต้องประกาศให้ผู้สมัครทราบก่อนปิดรับสมัคร และต้องไม่ขัดกับหลักเกณฑ์หลักตามระเบียบนี้\nหมวด ๕\nการได้มาซึ่งคณะกรรมการสภานักเรียน","keywords":["หมวด 4"],"sort_order":14},{"section_no":5,"clause_no":15,"title":"การรับสมัครให้ดำเนินการผ่านระบบสภานักเรียนของโรงเรียน หรือช่องทางที่โรงเรียนกำหนด โดยกำหนดวันเปิดรับสมัคร วันปิดรับสมัคร เอกสารประกอบ และรายละเอียดการดำเนินการให้ชัดเจน","body":"การรับสมัครให้ดำเนินการผ่านระบบสภานักเรียนของโรงเรียน หรือช่องทางที่โรงเรียนกำหนด โดยกำหนดวันเปิดรับสมัคร วันปิดรับสมัคร เอกสารประกอบ และรายละเอียดการดำเนินการให้ชัดเจน","keywords":["หมวด 5"],"sort_order":15},{"section_no":5,"clause_no":16,"title":"เมื่อปิดรับสมัคร ให้ครูที่ปรึกษาสภานักเรียนตรวจสอบคุณสมบัติและหลักฐานของผู้สมัคร ผู้ที่ผ่านเกณฑ์จึงมีสิทธิเข้ารับการสัมภาษณ์","body":"เมื่อปิดรับสมัคร ให้ครูที่ปรึกษาสภานักเรียนตรวจสอบคุณสมบัติและหลักฐานของผู้สมัคร ผู้ที่ผ่านเกณฑ์จึงมีสิทธิเข้ารับการสัมภาษณ์","keywords":["หมวด 5"],"sort_order":16},{"section_no":5,"clause_no":17,"title":"ให้ครูที่ปรึกษาสภานักเรียนดำเนินการสัมภาษณ์ผู้สมัคร โดยพิจารณาอย่างน้อยจากภาวะผู้นำ ความรับผิดชอบ จิตอาสา การสื่อสาร การทำงานร่วมกับผู้อื่น ความสามารถในการแก้ปัญหา ความเข้าใจบทบ...","body":"ให้ครูที่ปรึกษาสภานักเรียนดำเนินการสัมภาษณ์ผู้สมัคร โดยพิจารณาอย่างน้อยจากภาวะผู้นำ ความรับผิดชอบ จิตอาสา การสื่อสาร การทำงานร่วมกับผู้อื่น ความสามารถในการแก้ปัญหา ความเข้าใจบทบาทสภานักเรียน และความพร้อมในการปฏิบัติหน้าที่ควบคู่กับการเรียน","keywords":["หมวด 5"],"sort_order":17},{"section_no":5,"clause_no":18,"title":"ผู้สมัครที่ผ่านการสัมภาษณ์ให้มีสถานะเป็น “ว่าที่สมาชิกสภานักเรียน” และต้องเข้าร่วมกิจกรรมเสริมทักษะภาวะผู้นำ Youth Leadership For Azizstan (YLA) ตามที่โรงเรียนกำหนด","body":"ผู้สมัครที่ผ่านการสัมภาษณ์ให้มีสถานะเป็น “ว่าที่สมาชิกสภานักเรียน” และต้องเข้าร่วมกิจกรรมเสริมทักษะภาวะผู้นำ Youth Leadership For Azizstan (YLA) ตามที่โรงเรียนกำหนด","keywords":["หมวด 5"],"sort_order":18},{"section_no":5,"clause_no":19,"title":"กิจกรรม YLA มีวัตถุประสงค์เพื่อพัฒนาและประเมินศักยภาพของว่าที่สมาชิกสภานักเรียนในด้านภาวะผู้นำ การทำงานเป็นทีม การสื่อสาร การวางแผน การบริหารโครงการ การแก้ปัญหา ความรับผิดชอบ คุ...","body":"กิจกรรม YLA มีวัตถุประสงค์เพื่อพัฒนาและประเมินศักยภาพของว่าที่สมาชิกสภานักเรียนในด้านภาวะผู้นำ การทำงานเป็นทีม การสื่อสาร การวางแผน การบริหารโครงการ การแก้ปัญหา ความรับผิดชอบ คุณธรรม จริยธรรม และคุณลักษณะอื่นที่จำเป็นต่อการปฏิบัติหน้าที่","keywords":["หมวด 5"],"sort_order":19},{"section_no":5,"clause_no":20,"title":"ผลการเข้าร่วมกิจกรรม YLA ให้ใช้ประกอบการคัดเลือกสมาชิกสภานักเรียนตัวจริงและการจัดสมาชิกลงในแต่ละฝ่ายให้เหมาะสมกับความรู้ ความสามารถ ความสนใจ และศักยภาพของแต่ละบุคคล","body":"ผลการเข้าร่วมกิจกรรม YLA ให้ใช้ประกอบการคัดเลือกสมาชิกสภานักเรียนตัวจริงและการจัดสมาชิกลงในแต่ละฝ่ายให้เหมาะสมกับความรู้ ความสามารถ ความสนใจ และศักยภาพของแต่ละบุคคล","keywords":["หมวด 5"],"sort_order":20},{"section_no":5,"clause_no":21,"title":"เมื่อสิ้นสุดกระบวนการ YLA ให้คณะกรรมการที่รับผิดชอบเสนอรายชื่อว่าที่ผู้สมัครประธานสภานักเรียนชายจำนวน ๓ คน และว่าที่ผู้สมัครประธานสภานักเรียนหญิงจำนวน ๓ คน โดยพิจารณาจากคุณสมบัต...","body":"เมื่อสิ้นสุดกระบวนการ YLA ให้คณะกรรมการที่รับผิดชอบเสนอรายชื่อว่าที่ผู้สมัครประธานสภานักเรียนชายจำนวน ๓ คน และว่าที่ผู้สมัครประธานสภานักเรียนหญิงจำนวน ๓ คน โดยพิจารณาจากคุณสมบัติ ภาวะผู้นำ ผลการเข้าร่วม YLA ความรับผิดชอบ ความสามารถในการบริหารงาน และความเหมาะสมโดยรวม","keywords":["หมวด 5"],"sort_order":21},{"section_no":5,"clause_no":22,"title":"ผู้สมัครประธานสภานักเรียนมีสิทธิหาเสียงตามรูปแบบ ระยะเวลา พื้นที่ และช่องทางที่โรงเรียนกำหนด การหาเสียงต้องสุภาพ สร้างสรรค์ ไม่ใส่ร้าย ไม่ให้ข้อมูลเท็จ ไม่ซื้อเสียงหรือให้สิ่งตอ...","body":"ผู้สมัครประธานสภานักเรียนมีสิทธิหาเสียงตามรูปแบบ ระยะเวลา พื้นที่ และช่องทางที่โรงเรียนกำหนด การหาเสียงต้องสุภาพ สร้างสรรค์ ไม่ใส่ร้าย ไม่ให้ข้อมูลเท็จ ไม่ซื้อเสียงหรือให้สิ่งตอบแทนเพื่อจูงใจ และไม่ขัดต่อหลักการศาสนาและระเบียบโรงเรียน","keywords":["หมวด 5"],"sort_order":22},{"section_no":5,"clause_no":23,"title":"ก่อนการเลือกตั้ง ให้โรงเรียนออกประกาศหรือแนวปฏิบัติการเลือกตั้งประจำวาระ โดยอย่างน้อยต้องกำหนดผู้มีสิทธิเลือกตั้ง วิธีและช่องทางลงคะแนน วัน เวลา และสถานที่ วิธีรักษาความลับของกา...","body":"ก่อนการเลือกตั้ง ให้โรงเรียนออกประกาศหรือแนวปฏิบัติการเลือกตั้งประจำวาระ โดยอย่างน้อยต้องกำหนดผู้มีสิทธิเลือกตั้ง วิธีและช่องทางลงคะแนน วัน เวลา และสถานที่ วิธีรักษาความลับของการลงคะแนน หลักเกณฑ์บัตรเสียหรือคะแนนที่ไม่สมบูรณ์ วิธีนับและรับรองผล ระยะเวลาร้องเรียน และวิธีดำเนินการกรณีคะแนนเท่ากัน","keywords":["หมวด 5"],"sort_order":23},{"section_no":5,"clause_no":24,"title":"ให้ครูที่ปรึกษาสภานักเรียนหรือคณะกรรมการที่โรงเรียนแต่งตั้งเป็นผู้ควบคุมการเลือกตั้งและการนับคะแนนโดยยึดความเป็นกลาง ผู้สมัครและผู้สนับสนุนผู้สมัครต้องไม่ปฏิบัติหน้าที่ในส่วนที่...","body":"ให้ครูที่ปรึกษาสภานักเรียนหรือคณะกรรมการที่โรงเรียนแต่งตั้งเป็นผู้ควบคุมการเลือกตั้งและการนับคะแนนโดยยึดความเป็นกลาง ผู้สมัครและผู้สนับสนุนผู้สมัครต้องไม่ปฏิบัติหน้าที่ในส่วนที่สามารถเข้าถึง แก้ไข หรือรับรองคะแนนของตนเองได้","keywords":["หมวด 5"],"sort_order":24},{"section_no":5,"clause_no":25,"title":"ให้โรงเรียนจัดการเลือกตั้งประธานสภานักเรียนชายและประธานสภานักเรียนหญิง โดยนักเรียนผู้มีสิทธิเลือกตั้งตามหลักเกณฑ์ที่โรงเรียนประกาศ","body":"ให้โรงเรียนจัดการเลือกตั้งประธานสภานักเรียนชายและประธานสภานักเรียนหญิง โดยนักเรียนผู้มีสิทธิเลือกตั้งตามหลักเกณฑ์ที่โรงเรียนประกาศ","keywords":["หมวด 5"],"sort_order":25},{"section_no":5,"clause_no":26,"title":"ผลการเลือกตั้งของฝ่ายชายและฝ่ายหญิงให้จัดตำแหน่งดังต่อไปนี้","body":"ผลการเลือกตั้งของฝ่ายชายและฝ่ายหญิงให้จัดตำแหน่งดังต่อไปนี้\n(๑) ผู้ได้รับคะแนนสูงสุด เป็นประธานสภานักเรียน\n(๒) ผู้ได้รับคะแนนลำดับที่สอง เป็นรองประธานสภานักเรียน\n(๓) ผู้ได้รับคะแนนลำดับที่สาม เป็นเลขานุการสภานักเรียน","keywords":["หมวด 5"],"sort_order":26},{"section_no":5,"clause_no":27,"title":"ในกรณีคะแนนเท่ากัน หรือมีเหตุอันทำให้ไม่สามารถรับรองผลได้ ให้คณะกรรมการดำเนินการเลือกตั้งเสนอวิธีดำเนินการที่เหมาะสมต่อหัวหน้าฝ่ายปกครองและผู้บริหารโรงเรียนเพื่อพิจารณา","body":"ในกรณีคะแนนเท่ากัน หรือมีเหตุอันทำให้ไม่สามารถรับรองผลได้ ให้คณะกรรมการดำเนินการเลือกตั้งเสนอวิธีดำเนินการที่เหมาะสมต่อหัวหน้าฝ่ายปกครองและผู้บริหารโรงเรียนเพื่อพิจารณา","keywords":["หมวด 5"],"sort_order":27},{"section_no":5,"clause_no":28,"title":"เมื่อการจัดโครงสร้าง การกำหนดฝ่าย และการเลือกตั้งเสร็จสิ้น ให้ครูที่ปรึกษาสภานักเรียนจัดทำบัญชีรายชื่อและตำแหน่งเสนอผ่านหัวหน้าคณะครูที่ปรึกษาสภานักเรียนต่อผู้บริหารโรงเรียน เพื...","body":"เมื่อการจัดโครงสร้าง การกำหนดฝ่าย และการเลือกตั้งเสร็จสิ้น ให้ครูที่ปรึกษาสภานักเรียนจัดทำบัญชีรายชื่อและตำแหน่งเสนอผ่านหัวหน้าคณะครูที่ปรึกษาสภานักเรียนต่อผู้บริหารโรงเรียน เพื่อออกคำสั่งแต่งตั้งคณะกรรมการสภานักเรียนวาระใหม่","keywords":["หมวด 5"],"sort_order":28},{"section_no":5,"clause_no":29,"title":"บุคคลจะถือว่าเป็นคณะกรรมการสภานักเรียนโดยสมบูรณ์เมื่อมีชื่ออยู่ในคำสั่งแต่งตั้งของโรงเรียนแล้ว","body":"บุคคลจะถือว่าเป็นคณะกรรมการสภานักเรียนโดยสมบูรณ์เมื่อมีชื่ออยู่ในคำสั่งแต่งตั้งของโรงเรียนแล้ว","keywords":["หมวด 5"],"sort_order":29},{"section_no":5,"clause_no":30,"title":"ภายหลังคำสั่งแต่งตั้งคณะกรรมการสภานักเรียนมีผล ให้เลขานุการ ฝ่ายวิชาการ และฝ่ายสื่อสารสัมพันธ์ (ไอที) ร่วมกันดำเนินการจัดทำบัตรประจำตัวสภานักเรียนสำหรับสมาชิกทุกคนให้แล้วเสร็จภา...","body":"ภายหลังคำสั่งแต่งตั้งคณะกรรมการสภานักเรียนมีผล ให้เลขานุการ ฝ่ายวิชาการ และฝ่ายสื่อสารสัมพันธ์ (ไอที) ร่วมกันดำเนินการจัดทำบัตรประจำตัวสภานักเรียนสำหรับสมาชิกทุกคนให้แล้วเสร็จภายใน ๓๐ วันนับแต่วันที่คำสั่งแต่งตั้งมีผล โดยมีครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบเป็นผู้กำกับ ดูแล ตรวจสอบข้อมูล รูปแบบ การจัดพิมพ์ การลงทะเบียน และการส่งมอบบัตร","keywords":["หมวด 5"],"sort_order":30},{"section_no":5,"clause_no":31,"title":"บัตรประจำตัวสภานักเรียนควรมีข้อมูลที่จำเป็นอย่างน้อย ได้แก่ ชื่อและนามสกุล รูปถ่าย รหัสนักเรียน ระดับชั้น ตำแหน่งหรือฝ่าย วาระ และข้อมูลตรวจสอบตัวตนตามที่โรงเรียนกำหนด บัตรมีไว้...","body":"บัตรประจำตัวสภานักเรียนควรมีข้อมูลที่จำเป็นอย่างน้อย ได้แก่ ชื่อและนามสกุล รูปถ่าย รหัสนักเรียน ระดับชั้น ตำแหน่งหรือฝ่าย วาระ และข้อมูลตรวจสอบตัวตนตามที่โรงเรียนกำหนด บัตรมีไว้เพื่อแสดงสถานะในการปฏิบัติหน้าที่ มิได้ให้อำนาจลงโทษหรือสั่งการนักเรียนอื่น และให้สิ้นผลเมื่อสมาชิกพ้นจากตำแหน่ง โดยสมาชิกต้องคืนบัตรหรือดำเนินการตามวิธีที่โรงเรียนกำหนด\nหมวด ๖\nวาระ การพ้นจากตำแหน่ง และตำแหน่งว่าง","keywords":["หมวด 5"],"sort_order":31},{"section_no":6,"clause_no":32,"title":"คณะกรรมการสภานักเรียนมีวาระการดำรงตำแหน่งวาระละ ๑ ปีการศึกษา โดยเริ่มนับตั้งแต่วันที่คำสั่งแต่งตั้งมีผล เมื่อครบวาระให้คณะกรรมการชุดเดิมปฏิบัติหน้าที่ในลักษณะรักษาการเฉพาะเท่าที...","body":"คณะกรรมการสภานักเรียนมีวาระการดำรงตำแหน่งวาระละ ๑ ปีการศึกษา โดยเริ่มนับตั้งแต่วันที่คำสั่งแต่งตั้งมีผล เมื่อครบวาระให้คณะกรรมการชุดเดิมปฏิบัติหน้าที่ในลักษณะรักษาการเฉพาะเท่าที่จำเป็นจนกว่าคณะกรรมการสภานักเรียนวาระใหม่จะได้รับการแต่งตั้ง หรือจนกว่าโรงเรียนจะมีคำสั่งเป็นอย่างอื่น","keywords":["หมวด 6"],"sort_order":32},{"section_no":6,"clause_no":33,"title":"กรรมการสภานักเรียนพ้นจากตำแหน่งเมื่อครบวาระ พ้นสภาพนักเรียน ลาออก ขาดคุณสมบัติ ถูกให้พ้นจากตำแหน่ง หรือไม่สามารถปฏิบัติหน้าที่ได้ตามที่โรงเรียนพิจารณา","body":"กรรมการสภานักเรียนพ้นจากตำแหน่งเมื่อครบวาระ พ้นสภาพนักเรียน ลาออก ขาดคุณสมบัติ ถูกให้พ้นจากตำแหน่ง หรือไม่สามารถปฏิบัติหน้าที่ได้ตามที่โรงเรียนพิจารณา","keywords":["หมวด 6"],"sort_order":33},{"section_no":6,"clause_no":34,"title":"การลาออกให้ทำเป็นหนังสือหรือผ่านระบบที่โรงเรียนกำหนด ส่งผ่านครูที่ปรึกษาฝ่ายที่รับผิดชอบและหัวหน้าคณะครูที่ปรึกษาสภานักเรียนเพื่อเสนอผู้มีอำนาจรับทราบ","body":"การลาออกให้ทำเป็นหนังสือหรือผ่านระบบที่โรงเรียนกำหนด ส่งผ่านครูที่ปรึกษาฝ่ายที่รับผิดชอบและหัวหน้าคณะครูที่ปรึกษาสภานักเรียนเพื่อเสนอผู้มีอำนาจรับทราบ","keywords":["หมวด 6"],"sort_order":34},{"section_no":6,"clause_no":35,"title":"กรรมการอาจถูกพักหน้าที่หรือให้พ้นจากตำแหน่งเมื่อมีเหตุอันสมควร เช่น ทุจริต ใช้ตำแหน่งโดยมิชอบ ละทิ้งหน้าที่ซ้ำ ๆ ฝ่าฝืนระเบียบอย่างร้ายแรง หรือมีพฤติกรรมที่ทำให้เกิดความเสียหายต...","body":"กรรมการอาจถูกพักหน้าที่หรือให้พ้นจากตำแหน่งเมื่อมีเหตุอันสมควร เช่น ทุจริต ใช้ตำแหน่งโดยมิชอบ ละทิ้งหน้าที่ซ้ำ ๆ ฝ่าฝืนระเบียบอย่างร้ายแรง หรือมีพฤติกรรมที่ทำให้เกิดความเสียหายต่อโรงเรียน ทั้งนี้ต้องเปิดโอกาสให้ผู้เกี่ยวข้องชี้แจงข้อเท็จจริงก่อนการพิจารณา","keywords":["หมวด 6"],"sort_order":35},{"section_no":6,"clause_no":36,"title":"หากตำแหน่งประธานว่างลง ให้รองประธานทำหน้าที่รักษาการจนกว่าจะมีการแต่งตั้งหรือดำเนินการตามที่โรงเรียนกำหนด หากตำแหน่งอื่นว่างลง ให้คณะกรรมการสภานักเรียนเสนอผู้เหมาะสมผ่านครูที่ปร...","body":"หากตำแหน่งประธานว่างลง ให้รองประธานทำหน้าที่รักษาการจนกว่าจะมีการแต่งตั้งหรือดำเนินการตามที่โรงเรียนกำหนด หากตำแหน่งอื่นว่างลง ให้คณะกรรมการสภานักเรียนเสนอผู้เหมาะสมผ่านครูที่ปรึกษาเพื่อพิจารณาแต่งตั้งแทน\nหมวด ๗\nวินัย มาตรฐานความประพฤติ และการพิจารณาพ้นจากสมาชิกสภานักเรียน","keywords":["หมวด 6"],"sort_order":36},{"section_no":7,"clause_no":37,"title":"สมาชิกสภานักเรียนต้องประพฤติตนเป็นแบบอย่างที่ดีแก่เพื่อนนักเรียน และต้องปฏิบัติตามกฎ ระเบียบ ข้อบังคับ ประกาศ และแนวปฏิบัติของโรงเรียนอย่างเคร่งครัด โดยถือว่าการดำรงตำแหน่งสภานั...","body":"สมาชิกสภานักเรียนต้องประพฤติตนเป็นแบบอย่างที่ดีแก่เพื่อนนักเรียน และต้องปฏิบัติตามกฎ ระเบียบ ข้อบังคับ ประกาศ และแนวปฏิบัติของโรงเรียนอย่างเคร่งครัด โดยถือว่าการดำรงตำแหน่งสภานักเรียนเป็นความรับผิดชอบเพิ่มเติมจากสถานะนักเรียนทั่วไป","keywords":["หมวด 7"],"sort_order":37},{"section_no":7,"clause_no":38,"title":"เมื่อสมาชิกสภานักเรียนกระทำความผิดที่มีเกณฑ์การตัดคะแนนความประพฤติตามระเบียบของโรงเรียน ให้ตัดคะแนนความประพฤติเป็นสองเท่าของอัตราที่กำหนดสำหรับนักเรียนทั่วไปในความผิดประเภทเดียว...","body":"เมื่อสมาชิกสภานักเรียนกระทำความผิดที่มีเกณฑ์การตัดคะแนนความประพฤติตามระเบียบของโรงเรียน ให้ตัดคะแนนความประพฤติเป็นสองเท่าของอัตราที่กำหนดสำหรับนักเรียนทั่วไปในความผิดประเภทเดียวกัน ส่วนการลงโทษหรือมาตรการอื่นให้ดำเนินการตามระเบียบของโรงเรียนและระเบียบกระทรวงศึกษาธิการที่ใช้บังคับ โดยคำนึงถึงอายุ ลักษณะ และความร้ายแรงของพฤติการณ์ ทั้งนี้ การดำเนินการและการบันทึกโทษเป็นอำนาจของฝ่ายปกครองหรือผู้ได้รับมอบหมาย มิใช่อำนาจของสภานักเรียนหรือสมาชิกสภานักเรียนด้วยกันเอง","keywords":["หมวด 7"],"sort_order":38},{"section_no":7,"clause_no":39,"title":"สมาชิกสภานักเรียนชายต้องเข้ารายงานและตรวจทรงผมกับครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบด้านปกครองตามรอบประจำสัปดาห์ที่กำหนด หากตรวจพบว่าทรงผมหรือความยาวของผมไม่เป็นไปตามระเบียบโรงเ...","body":"สมาชิกสภานักเรียนชายต้องเข้ารายงานและตรวจทรงผมกับครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบด้านปกครองตามรอบประจำสัปดาห์ที่กำหนด หากตรวจพบว่าทรงผมหรือความยาวของผมไม่เป็นไปตามระเบียบโรงเรียน ให้ถือเป็นการผิดวินัยของสภานักเรียนและดำเนินการตามหลักเกณฑ์ดังต่อไปนี้\n(๑) กรณีนักเรียนทั่วไปถูกหักคะแนนความประพฤติ ๕ คะแนน สมาชิกสภานักเรียนให้ถูกหักคะแนนเป็นสองเท่า คือ ๑๐ คะแนน\n(๒) ผู้ที่ถูกหักคะแนนต้องแก้ไขทรงผมให้ถูกต้องและกลับมารายงานต่อครูผู้รับผิดชอบในสัปดาห์ถัดไป หากไม่มารายงานตามกำหนด ให้ถูกหักคะแนนเพิ่มสัปดาห์ละ ๑๐ คะแนน จนกว่าจะมารายงานและแก้ไขเรียบร้อย\n(๓) สมาชิกสภานักเรียนต้องดำเนินการแก้ไขทรงผมและรายงานให้เสร็จสิ้นภายในเดือนที่พบการกระทำผิด เว้นแต่มีเหตุจำเป็นที่ครูผู้รับผิดชอบเห็นสมควร","keywords":["หมวด 7"],"sort_order":39},{"section_no":7,"clause_no":40,"title":"สมาชิกสภานักเรียนหญิงต้องรายงานและรับการตรวจความเรียบร้อยของเครื่องแต่งกายกับครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบด้านปกครองตามรอบที่กำหนด โดยให้ตรวจเป็นพิเศษในเรื่องเสื้อ เครื่อง...","body":"สมาชิกสภานักเรียนหญิงต้องรายงานและรับการตรวจความเรียบร้อยของเครื่องแต่งกายกับครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบด้านปกครองตามรอบที่กำหนด โดยให้ตรวจเป็นพิเศษในเรื่องเสื้อ เครื่องแต่งกาย และผ้าคลุม หากพบการแต่งกายไม่เป็นไปตามระเบียบโรงเรียน ให้ดำเนินการตามหลักเกณฑ์การลงโทษและการหักคะแนนสำหรับสมาชิกสภานักเรียนตามข้อ ๓๘","keywords":["หมวด 7"],"sort_order":40},{"section_no":7,"clause_no":41,"title":"เมื่อสมาชิกสภานักเรียนมีคะแนนความประพฤติถูกหักสะสมถึง ๕๐ คะแนน ให้ครูที่ปรึกษาสภานักเรียนเรียกเจ้าตัวเข้าชี้แจงข้อเท็จจริง ทบทวนพฤติกรรม และจัดทำข้อตกลงขั้นสุดท้ายเป็นลายลักษณ์อ...","body":"เมื่อสมาชิกสภานักเรียนมีคะแนนความประพฤติถูกหักสะสมถึง ๕๐ คะแนน ให้ครูที่ปรึกษาสภานักเรียนเรียกเจ้าตัวเข้าชี้แจงข้อเท็จจริง ทบทวนพฤติกรรม และจัดทำข้อตกลงขั้นสุดท้ายเป็นลายลักษณ์อักษร โดยมีครูที่ปรึกษาผู้รับผิดชอบและหัวหน้าคณะครูที่ปรึกษาสภานักเรียนรับทราบ","keywords":["หมวด 7"],"sort_order":41},{"section_no":7,"clause_no":42,"title":"ภายหลังการจัดทำข้อตกลงขั้นสุดท้ายตามข้อ ๔๑ หากสมาชิกสภานักเรียนถูกหักคะแนนความประพฤติเพิ่มอีก ให้เข้าสู่กระบวนการพิจารณาให้ออกจากสภานักเรียน โดยให้ตรวจสอบข้อเท็จจริง เปิดโอกาสให...","body":"ภายหลังการจัดทำข้อตกลงขั้นสุดท้ายตามข้อ ๔๑ หากสมาชิกสภานักเรียนถูกหักคะแนนความประพฤติเพิ่มอีก ให้เข้าสู่กระบวนการพิจารณาให้ออกจากสภานักเรียน โดยให้ตรวจสอบข้อเท็จจริง เปิดโอกาสให้เจ้าตัวชี้แจง และเสนอผลการพิจารณาตามสายงานต่อหัวหน้าฝ่ายปกครองและผู้บริหารโรงเรียนก่อนออกคำสั่งหรือรับรองการพ้นจากตำแหน่ง","keywords":["หมวด 7"],"sort_order":42},{"section_no":7,"clause_no":43,"title":"สมาชิกสภานักเรียนที่มีพฤติกรรมคบหากันในลักษณะคู่รักหรือชู้สาวอันขัดต่อระเบียบของโรงเรียนหรือหลักการศาสนาอิสลาม เมื่อมีข้อเท็จจริงหรือหลักฐานที่ชัดเจนและผ่านการตรวจสอบแล้ว ให้เข้...","body":"สมาชิกสภานักเรียนที่มีพฤติกรรมคบหากันในลักษณะคู่รักหรือชู้สาวอันขัดต่อระเบียบของโรงเรียนหรือหลักการศาสนาอิสลาม เมื่อมีข้อเท็จจริงหรือหลักฐานที่ชัดเจนและผ่านการตรวจสอบแล้ว ให้เข้าสู่กระบวนการพิจารณาคัดออกจากสภานักเรียน ทั้งนี้ ต้องเปิดโอกาสให้ผู้เกี่ยวข้องชี้แจงก่อนมีข้อสรุป","keywords":["หมวด 7"],"sort_order":43},{"section_no":7,"clause_no":44,"title":"สมาชิกสภานักเรียนที่มีพฤติกรรมเกี่ยวข้องกับยาเสพติด ไม่ว่าจะเป็นการเสพ ครอบครอง จำหน่าย ชักชวน หรือเกี่ยวข้องในลักษณะอื่นตามที่ระเบียบโรงเรียนกำหนด ให้ดำเนินการตามระเบียบของโรงเ...","body":"สมาชิกสภานักเรียนที่มีพฤติกรรมเกี่ยวข้องกับยาเสพติด ไม่ว่าจะเป็นการเสพ ครอบครอง จำหน่าย ชักชวน หรือเกี่ยวข้องในลักษณะอื่นตามที่ระเบียบโรงเรียนกำหนด ให้ดำเนินการตามระเบียบของโรงเรียนและให้พ้นจากการเป็นสมาชิกสภานักเรียน เมื่อข้อเท็จจริงได้รับการยืนยันตามกระบวนการของโรงเรียน","keywords":["หมวด 7"],"sort_order":44},{"section_no":7,"clause_no":45,"title":"สมาชิกสภานักเรียนที่มีพฤติกรรมทำร้ายร่างกาย ทะเลาะวิวาท หรือร่วมก่อเหตุทะเลาะเบาะแว้ง ให้ดำเนินการตามระเบียบของโรงเรียนและให้พ้นจากการเป็นสมาชิกสภานักเรียน เมื่อข้อเท็จจริงได้รั...","body":"สมาชิกสภานักเรียนที่มีพฤติกรรมทำร้ายร่างกาย ทะเลาะวิวาท หรือร่วมก่อเหตุทะเลาะเบาะแว้ง ให้ดำเนินการตามระเบียบของโรงเรียนและให้พ้นจากการเป็นสมาชิกสภานักเรียน เมื่อข้อเท็จจริงได้รับการยืนยันตามกระบวนการของโรงเรียน","keywords":["หมวด 7"],"sort_order":45},{"section_no":7,"clause_no":46,"title":"ในกรณีความผิดร้ายแรงอื่นที่มิได้ระบุไว้ในหมวดนี้ แต่มีลักษณะขัดต่อคุณสมบัติของการเป็นผู้นำนักเรียน กระทบต่อความปลอดภัย คุณธรรม จริยธรรม หลักการศาสนา หรือชื่อเสียงของโรงเรียนอย่า...","body":"ในกรณีความผิดร้ายแรงอื่นที่มิได้ระบุไว้ในหมวดนี้ แต่มีลักษณะขัดต่อคุณสมบัติของการเป็นผู้นำนักเรียน กระทบต่อความปลอดภัย คุณธรรม จริยธรรม หลักการศาสนา หรือชื่อเสียงของโรงเรียนอย่างมีนัยสำคัญ ให้หัวหน้าคณะครูที่ปรึกษาสภานักเรียนเสนอเรื่องต่อหัวหน้าฝ่ายปกครองและผู้บริหารโรงเรียนเพื่อพิจารณาพักหน้าที่หรือให้พ้นจากการเป็นสมาชิกสภานักเรียนตามความเหมาะสม","keywords":["หมวด 7"],"sort_order":46},{"section_no":7,"clause_no":47,"title":"การพิจารณาลงโทษ พักหน้าที่ หรือให้พ้นจากการเป็นสมาชิกสภานักเรียนตามหมวดนี้ ต้องอาศัยข้อเท็จจริงและหลักฐานที่ตรวจสอบได้ คำนึงถึงความเป็นธรรมและความเหมาะสม เปิดโอกาสให้ผู้เกี่ยวข้...","body":"การพิจารณาลงโทษ พักหน้าที่ หรือให้พ้นจากการเป็นสมาชิกสภานักเรียนตามหมวดนี้ ต้องอาศัยข้อเท็จจริงและหลักฐานที่ตรวจสอบได้ คำนึงถึงความเป็นธรรมและความเหมาะสม เปิดโอกาสให้ผู้เกี่ยวข้องชี้แจง และเก็บบันทึกผลการดำเนินการไว้เป็นหลักฐานของงานกิจกรรมนักเรียน ฝ่ายปกครอง\nหมวด ๘\nอำนาจและหน้าที่ของสภานักเรียน","keywords":["หมวด 7"],"sort_order":47},{"section_no":8,"clause_no":48,"title":"สภานักเรียนมีอำนาจและหน้าที่ภายใต้การกำกับดูแลของโรงเรียน ดังต่อไปนี้","body":"สภานักเรียนมีอำนาจและหน้าที่ภายใต้การกำกับดูแลของโรงเรียน ดังต่อไปนี้\n(๑) เสนอความคิดเห็น ข้อเสนอแนะ และแนวทางพัฒนากิจกรรมหรือคุณภาพชีวิตของนักเรียนต่อโรงเรียน\n(๒) เป็นตัวแทนนักเรียนในการประสานงานกับครู ฝ่ายงาน และผู้บริหารในเรื่องที่ได้รับมอบหมาย\n(๓) เสนอ วางแผน และดำเนินโครงการหรือกิจกรรมของนักเรียนภายใต้การอนุมัติของโรงเรียน\n(๔) ส่งเสริมกิจกรรมด้านศาสนา คุณธรรม จิตอาสา วิชาการ กีฬา สุขภาวะ นันทนาการ และกิจกรรมสร้างสรรค์\n(๕) รับฟัง รวบรวม และสะท้อนความคิดเห็นของนักเรียนต่อฝ่ายที่เกี่ยวข้องอย่างเหมาะสม\n(๖) ช่วยประสานงานและอำนวยความสะดวกในการจัดกิจกรรมต่าง ๆ ตามที่โรงเรียนมอบหมาย\n(๗) จัดประชุม วางแผน ติดตาม และรายงานผลการดำเนินงานของแต่ละฝ่าย\n(๘) ดูแลเอกสาร ทรัพย์สิน ข้อมูล และทรัพยากรที่ได้รับมอบหมายอย่างรับผิดชอบ\n(๙) ปฏิบัติหน้าที่อื่นตามที่งานกิจกรรมนักเรียน ฝ่ายปกครอง หรือผู้บริหารโรงเรียนมอบหมาย","keywords":["หมวด 8"],"sort_order":48},{"section_no":8,"clause_no":49,"title":"สภานักเรียนไม่มีอำนาจลงโทษนักเรียนโดยเด็ดขาด รวมถึงไม่มีอำนาจตัดคะแนนความประพฤติ สั่งทำโทษ กำหนดโทษทางวินัย หรือใช้อำนาจแทนครูหรือฝ่ายปกครอง","body":"สภานักเรียนไม่มีอำนาจลงโทษนักเรียนโดยเด็ดขาด รวมถึงไม่มีอำนาจตัดคะแนนความประพฤติ สั่งทำโทษ กำหนดโทษทางวินัย หรือใช้อำนาจแทนครูหรือฝ่ายปกครอง","keywords":["หมวด 8"],"sort_order":49},{"section_no":8,"clause_no":50,"title":"เมื่อสมาชิกสภานักเรียนพบการกระทำที่อาจฝ่าฝืนระเบียบโรงเรียน ให้ดำเนินการได้เพียงการแจ้งเตือนด้วยถ้อยคำที่เหมาะสมในกรณีทั่วไป การบันทึกหรือรายงานข้อเท็จจริง และส่งต่อเรื่องให้ครู...","body":"เมื่อสมาชิกสภานักเรียนพบการกระทำที่อาจฝ่าฝืนระเบียบโรงเรียน ให้ดำเนินการได้เพียงการแจ้งเตือนด้วยถ้อยคำที่เหมาะสมในกรณีทั่วไป การบันทึกหรือรายงานข้อเท็จจริง และส่งต่อเรื่องให้ครูผู้ปฏิบัติหน้าที่เวรประจำวัน ครูที่เกี่ยวข้อง หรือฝ่ายปกครองเป็นผู้พิจารณาดำเนินการตามอำนาจหน้าที่","keywords":["หมวด 8"],"sort_order":50},{"section_no":8,"clause_no":51,"title":"สมาชิกสภานักเรียนต้องไม่ใช้อำนาจ ตำแหน่ง เครื่องหมาย หรือชื่อของสภานักเรียนเพื่อข่มขู่ กดดัน แสวงหาประโยชน์ส่วนตน หรือสร้างความเสียหายแก่ผู้อื่น","body":"สมาชิกสภานักเรียนต้องไม่ใช้อำนาจ ตำแหน่ง เครื่องหมาย หรือชื่อของสภานักเรียนเพื่อข่มขู่ กดดัน แสวงหาประโยชน์ส่วนตน หรือสร้างความเสียหายแก่ผู้อื่น\nหมวด ๙\nหน้าที่ของตำแหน่งสำคัญและฝ่ายต่าง ๆ","keywords":["หมวด 8"],"sort_order":51},{"section_no":9,"clause_no":52,"title":"ประธานสภานักเรียนชายและประธานสภานักเรียนหญิงมีหน้าที่เป็นผู้นำการดำเนินงานของสภานักเรียนในส่วนของตน กำหนดทิศทางและเป้าหมายการทำงาน เป็นประธานการประชุม มอบหมายและติดตามงานของตำแห...","body":"ประธานสภานักเรียนชายและประธานสภานักเรียนหญิงมีหน้าที่เป็นผู้นำการดำเนินงานของสภานักเรียนในส่วนของตน กำหนดทิศทางและเป้าหมายการทำงาน เป็นประธานการประชุม มอบหมายและติดตามงานของตำแหน่งและฝ่ายต่าง ๆ ประสานการทำงานระหว่างฝ่าย ให้คำแนะนำและแก้ไขปัญหาเบื้องต้น เป็นตัวแทนนักเรียนในกิจการที่ได้รับมอบหมาย ประสานงานร่วมกับประธานอีกฝ่ายในกิจกรรมส่วนรวม และรายงานผลการดำเนินงานหรือปัญหาสำคัญต่อครูที่ปรึกษาสภานักเรียนตามสายงาน","keywords":["หมวด 9"],"sort_order":52},{"section_no":9,"clause_no":53,"title":"รองประธานสภานักเรียนมีหน้าที่ช่วยเหลือประธานในการกำกับ ติดตาม และประสานงานของฝ่ายต่าง ๆ โดยเฉพาะงานที่ต้องอาศัยความร่วมมือหลายฝ่าย ติดตามความพร้อมของกำลังคน วัสดุ สถานที่ และการ...","body":"รองประธานสภานักเรียนมีหน้าที่ช่วยเหลือประธานในการกำกับ ติดตาม และประสานงานของฝ่ายต่าง ๆ โดยเฉพาะงานที่ต้องอาศัยความร่วมมือหลายฝ่าย ติดตามความพร้อมของกำลังคน วัสดุ สถานที่ และการสื่อสาร ปฏิบัติภารกิจตามที่ประธานหรือครูที่ปรึกษามอบหมาย และทำหน้าที่แทนประธานเมื่อประธานไม่สามารถปฏิบัติหน้าที่ได้","keywords":["หมวด 9"],"sort_order":53},{"section_no":9,"clause_no":54,"title":"เลขานุการมีหน้าที่จัดทำระเบียบวาระและบันทึกการประชุม ดูแลหนังสือ เอกสาร รายชื่อผู้เข้าร่วม มติ ปฏิทินงาน และหลักฐานสำคัญของสภานักเรียน ประสานการจัดทำหนังสือหรือเอกสารภายในที่เกี...","body":"เลขานุการมีหน้าที่จัดทำระเบียบวาระและบันทึกการประชุม ดูแลหนังสือ เอกสาร รายชื่อผู้เข้าร่วม มติ ปฏิทินงาน และหลักฐานสำคัญของสภานักเรียน ประสานการจัดทำหนังสือหรือเอกสารภายในที่เกี่ยวข้อง ติดตามเอกสารจากฝ่ายต่าง ๆ ให้ครบถ้วน และร่วมกับฝ่ายวิชาการและฝ่ายสื่อสารสัมพันธ์ (ไอที) จัดทำและดูแลทะเบียนบัตรประจำตัวสภานักเรียนตามระเบียบนี้ ส่วนรองเลขานุการมีหน้าที่ช่วยเหลือเลขานุการ ดูแลการลงทะเบียน การรวบรวมเอกสาร การติดตามงานเอกสาร ปฏิบัติหน้าที่ตามที่ได้รับมอบหมาย และทำหน้าที่แทนเลขานุการเมื่อเลขานุการไม่สามารถปฏิบัติหน้าที่ได้","keywords":["หมวด 9"],"sort_order":54},{"section_no":9,"clause_no":55,"title":"ฝ่ายต่าง ๆ และเหรัญญิกของสภานักเรียนชายและสภานักเรียนหญิงมีหน้าที่หลักดังต่อไปนี้ ทั้งนี้ ทุกฝ่ายต้องทำงานในลักษณะประสานและสนับสนุนซึ่งกันและกัน ไม่ถือว่าภารกิจใดเป็นหน้าที่ของฝ...","body":"ฝ่ายต่าง ๆ และเหรัญญิกของสภานักเรียนชายและสภานักเรียนหญิงมีหน้าที่หลักดังต่อไปนี้ ทั้งนี้ ทุกฝ่ายต้องทำงานในลักษณะประสานและสนับสนุนซึ่งกันและกัน ไม่ถือว่าภารกิจใดเป็นหน้าที่ของฝ่ายใดฝ่ายหนึ่งโดยลำพัง เมื่อกิจกรรมหรือภารกิจมีความเกี่ยวข้องหลายฝ่าย ให้ฝ่ายที่รับผิดชอบหลักเป็นผู้ประสานและขอความร่วมมือจากฝ่ายอื่น โดยมีประธาน รองประธาน และครูที่ปรึกษาผู้รับผิดชอบกำกับให้การดำเนินงานเป็นไปในทิศทางเดียวกัน\n(๑) ฝ่ายวิชาการ มีหน้าที่คิดริเริ่มและสนับสนุนกิจกรรมที่เกี่ยวข้องกับด้านวิชาการ จัดทำ ร่าง และตรวจสอบเอกสารโครงการ เช่น ใบเสนอหรือขออนุมัติโครงการ หนังสือหรือใบอนุญาตที่เกี่ยวข้อง แบบประเมิน และรายงานสรุปผลกิจกรรม เป็นที่ปรึกษาและช่วยเหลือฝ่ายอื่นในการเขียนโครงการและจัดทำเอกสารให้ถูกต้องครบถ้วน รวบรวมข้อมูลที่ใช้ประกอบการประเมินผล ตลอดจนร่วมกับเลขานุการและฝ่ายสื่อสารสัมพันธ์ (ไอที) ในการจัดทำบัตรประจำตัวสภานักเรียน\n(๒) ฝ่ายปกครอง มีหน้าที่ช่วยส่งเสริมให้นักเรียนปฏิบัติตามกฎ ระเบียบ และข้อกำหนดของโรงเรียน สังเกตและเฝ้าระวังความเรียบร้อยในพื้นที่หรือกิจกรรมที่ได้รับมอบหมาย เป็นผู้ช่วยสอดส่องและรายงานเหตุให้ครูผู้ปฏิบัติหน้าที่เวรประจำวัน ครูที่ปรึกษา หรือฝ่ายปกครองทราบ บันทึกชื่อและข้อเท็จจริงเกี่ยวกับเหตุหรือพฤติกรรมที่พบลงในทะเบียนบันทึกเหตุหรือระบบที่โรงเรียนกำหนด และประสานนำผู้เกี่ยวข้องส่งต่อให้ครูผู้มีอำนาจพิจารณาดำเนินการ ทั้งนี้ สมาชิกฝ่ายปกครองไม่มีอำนาจลงโทษ ตัดคะแนนความประพฤติ บังคับใช้มาตรการทางวินัย หรือกระทำการแทนครูฝ่ายปกครอง\n(๓) ฝ่ายอาคารสถานที่ มีหน้าที่ตรวจสอบความเรียบร้อยของอาคาร ห้องเรียน ห้องน้ำ และพื้นที่ต่าง ๆ ภายในโรงเรียนตามขอบเขตที่ได้รับมอบหมาย โดยเฉพาะช่วงก่อนการเข้าแถวในตอนเช้า เพื่อสังเกตนักเรียนที่ยังอยู่ตามอาคารหรือหลีกเลี่ยงการเข้าแถว และแจ้งให้นักเรียนรีบลงไปเข้าแถวให้ทันเวลา ตรวจสอบความพร้อม ความสะอาด และความเป็นระเบียบของพื้นที่ ตลอดจนสำรวจ เตรียม และดูแลสถานที่ อุปกรณ์ โต๊ะ เก้าอี้ ป้าย และจุดบริการสำหรับการประชุมหรือกิจกรรม และประสานฝ่ายที่เกี่ยวข้องเมื่อพบความชำรุดหรือปัญหาด้านสถานที่\n(๔) ฝ่ายนันทนาการและสวัสดิการ มีหน้าที่คิดริเริ่ม ออกแบบ และร่วมดำเนินกิจกรรมนันทนาการหรือกิจกรรมสร้างความสัมพันธ์ จัดหา เตรียม และดูแลวัสดุหรืออุปกรณ์ที่ใช้ในการดำเนินกิจกรรม ช่วยวางรูปแบบและควบคุมกิจกรรมที่เกี่ยวข้องกับการเข้าแถวหรือกิจกรรมรวมหมู่ตามที่ได้รับมอบหมาย รวมทั้งดูแลสวัสดิการและการอำนวยความสะดวกแก่สมาชิกสภานักเรียนและผู้เข้าร่วมกิจกรรม เช่น น้ำดื่ม อาหาร จุดพัก การต้อนรับ และความต้องการพื้นฐานอื่น ภายใต้งบประมาณและการอนุมัติของโรงเรียน\n(๕) ฝ่ายศาสนสัมพันธ์ (อีบาดัต) มีหน้าที่สนับสนุนและประสานกิจกรรมด้านศาสนา คุณธรรม และการปฏิบัติศาสนกิจของนักเรียน ช่วยดูแลความเป็นระเบียบในการละหมาด จัดทำและประกาศตารางเวรที่เกี่ยวข้องกับการละหมาด เช่น เวรอิหม่าม เวรบันทึกหรือประทับตราการละหมาด และเวรบันทึกอูโซร์ตามระบบที่โรงเรียนกำหนด โดยระบุผู้รับผิดชอบในแต่ละวันอย่างชัดเจน ติดตามให้การปฏิบัติหน้าที่เป็นไปตามตาราง สนับสนุนกิจกรรมที่ฝ่ายวิชาการศาสนาหรือโรงเรียนเป็นผู้รับผิดชอบ และประสานฝ่ายอื่นเพื่อให้กิจกรรมเป็นไปตามหลักการศาสนาอิสลามและบริบทของโรงเรียน\n(๖) ฝ่ายประชาสัมพันธ์ มีหน้าที่รับผิดชอบการสื่อสารข่าวสารภายในโรงเรียน โดยเฉพาะการเรียกและจัดแถวในช่วงเช้า ซึ่งต้องปฏิบัติหน้าที่ด้วยความตรงต่อเวลาเพื่อไม่ให้กระทบต่อเวลาเข้าเรียนคาบแรก ประกาศหรือประชาสัมพันธ์ข้อมูลที่โรงเรียนและสภานักเรียนมอบหมาย เช่น การแจ้งรับพัสดุ การเรียกพบนักเรียนที่ห้องการเงิน ห้องปกครอง ห้องประชาสัมพันธ์ หรือหน่วยงานอื่น จัดเตรียมข้อความและลำดับการประกาศให้ถูกต้องชัดเจน และประสานกับฝ่ายมวลชนสัมพันธ์ ฝ่ายสื่อสารสัมพันธ์ (ไอที) และฝ่ายที่เกี่ยวข้องเพื่อให้ข่าวสารเข้าถึงนักเรียนอย่างทั่วถึง\n(๗) ฝ่ายสื่อสารสัมพันธ์ (ไอที) มีหน้าที่สนับสนุนงานด้านเทคโนโลยีและสื่อดิจิทัลของสภานักเรียน จัดทำป้ายหรือบัตรประจำตัวสภานักเรียนและบอร์ดทำเนียบสภานักเรียน ผลิตวิดีโอ ภาพกราฟิก หรือสื่อสร้างสรรค์เพื่อประชาสัมพันธ์ รณรงค์ หรือสื่อสารตามกิจกรรมและสถานการณ์ อัปเดตข่าวสาร ภาพ และวิดีโอเกี่ยวกับกิจกรรมภายในโรงเรียน ดูแลหรือร่วมเป็นผู้ดูแลช่องทางสื่อออนไลน์ที่โรงเรียนมอบหมาย เช่น DEPaz Media ตลอดจนสนับสนุนระบบดิจิทัล ฐานข้อมูล อุปกรณ์ภาพและเสียง หรือเทคโนโลยีที่เกี่ยวข้องกับกิจกรรม โดยต้องเผยแพร่ข้อมูลตามแนวทางและการอนุญาตของโรงเรียน และร่วมกับเลขานุการและฝ่ายวิชาการจัดทำบัตรประจำตัวสภานักเรียนให้แล้วเสร็จภายในระยะเวลาที่กำหนด\n(๘) ฝ่ายมวลชนสัมพันธ์ มีหน้าที่เป็นตัวกลางเชื่อมโยงระหว่างสภานักเรียนกับหัวหน้าห้องและเครือข่ายนักเรียนในแต่ละห้อง จัดหรือร่วมจัดกิจกรรมสานสัมพันธ์ระหว่างหัวหน้าห้องกับสภานักเรียน สื่อสารข่าวสารหรือภารกิจผ่านหัวหน้าห้องเพื่อให้ถ่ายทอดต่อไปยังนักเรียนในห้อง รับฟังและรวบรวมข้อเสนอแนะ ปัญหา หรือข้อมูลจากหัวหน้าห้องกลับมายังสภานักเรียน ดูแลระบบหรือบัตรแสดงตนของหัวหน้าห้องตามที่โรงเรียนกำหนด และส่งเสริมความสัมพันธ์ ความไว้วางใจ และความร่วมมือระหว่างผู้นำนักเรียนระดับห้องกับสภานักเรียน\n(๙) เหรัญญิก มีหน้าที่จัดทำและดูแลทะเบียนรับ–จ่าย บัญชี และหลักฐานทางการเงินที่เกี่ยวข้องกับสภานักเรียน บันทึกและติดตามค่าผ้าชุดสภา เงินสำรอง และเงินออมรายบุคคลตามหลักเกณฑ์ที่กำหนด ตรวจสอบยอดคงเหลือ จัดทำสรุปสถานะทางการเงินและรายงานต่อครูที่ปรึกษาผู้รับผิดชอบ ประสานฝ่ายวิชาการและฝ่ายที่จัดกิจกรรมเพื่อประมาณการและติดตามค่าใช้จ่าย ตลอดจนประสานการคืนเงินหรือการชำระค่าใช้จ่ายตามสิทธิของสมาชิก ทั้งนี้ การรับ จ่าย เก็บรักษา หรือคืนเงินทุกประเภทต้องเป็นไปตามระบบการเงินของโรงเรียน มีหลักฐานตรวจสอบได้ และไม่ให้สมาชิกถือหรือใช้เงินนอกเหนือจากที่ได้รับอนุมัติ","keywords":["หมวด 9"],"sort_order":55},{"section_no":9,"clause_no":56,"title":"สมาชิกทุกตำแหน่งและทุกฝ่ายต้องปฏิบัติงานตามแผนและภารกิจที่ได้รับมอบหมาย เข้าร่วมประชุมและกิจกรรมอย่างสม่ำเสมอ ประสานและให้ความร่วมมือกับฝ่ายอื่นตามความจำเป็น โดยยึดประโยชน์ของกิ...","body":"สมาชิกทุกตำแหน่งและทุกฝ่ายต้องปฏิบัติงานตามแผนและภารกิจที่ได้รับมอบหมาย เข้าร่วมประชุมและกิจกรรมอย่างสม่ำเสมอ ประสานและให้ความร่วมมือกับฝ่ายอื่นตามความจำเป็น โดยยึดประโยชน์ของกิจกรรมและนักเรียนเป็นสำคัญ หากภารกิจมีความคาบเกี่ยวหรือไม่ชัดเจนว่าอยู่ในความรับผิดชอบของฝ่ายใด ให้ประธานหรือรองประธานประสานครูที่ปรึกษาผู้รับผิดชอบเพื่อกำหนดฝ่ายหลักและฝ่ายสนับสนุน และให้แต่ละฝ่ายรายงานปัญหา ความคืบหน้า และผลการดำเนินงานต่อผู้รับผิดชอบฝ่าย ประธานสภานักเรียน และครูที่ปรึกษาตามลำดับ\nหมวด ๑๐\nการประชุมและการลงมติ","keywords":["หมวด 9"],"sort_order":56},{"section_no":10,"clause_no":57,"title":"ให้มีการประชุมคณะกรรมการสภานักเรียนตามความจำเป็น โดยกำหนดวัน เวลา สถานที่ และรูปแบบที่ไม่กระทบต่อการเรียน การละหมาด และภารกิจสำคัญของโรงเรียน","body":"ให้มีการประชุมคณะกรรมการสภานักเรียนตามความจำเป็น โดยกำหนดวัน เวลา สถานที่ และรูปแบบที่ไม่กระทบต่อการเรียน การละหมาด และภารกิจสำคัญของโรงเรียน","keywords":["หมวด 10"],"sort_order":57},{"section_no":10,"clause_no":58,"title":"การประชุมควรมีระเบียบวาระ ได้แก่ เรื่องแจ้งเพื่อทราบ รับรองรายงานการประชุม เรื่องสืบเนื่อง เรื่องเพื่อพิจารณา และเรื่องอื่น ๆ ตามความเหมาะสม","body":"การประชุมควรมีระเบียบวาระ ได้แก่ เรื่องแจ้งเพื่อทราบ รับรองรายงานการประชุม เรื่องสืบเนื่อง เรื่องเพื่อพิจารณา และเรื่องอื่น ๆ ตามความเหมาะสม","keywords":["หมวด 10"],"sort_order":58},{"section_no":10,"clause_no":59,"title":"องค์ประชุมต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของกรรมการที่มีสิทธิทำหน้าที่ในขณะนั้น เว้นแต่เป็นการประชุมย่อยของฝ่าย","body":"องค์ประชุมต้องมีกรรมการมาประชุมไม่น้อยกว่ากึ่งหนึ่งของกรรมการที่มีสิทธิทำหน้าที่ในขณะนั้น เว้นแต่เป็นการประชุมย่อยของฝ่าย","keywords":["หมวด 10"],"sort_order":59},{"section_no":10,"clause_no":60,"title":"การลงมติให้ใช้เสียงข้างมากของผู้เข้าประชุมที่มีสิทธิออกเสียง หากคะแนนเท่ากัน ให้ประธานในที่ประชุมออกเสียงเพิ่มอีกหนึ่งเสียงเป็นเสียงชี้ขาด ทั้งนี้มติที่มีผลต่อระเบียบ การเงิน คว...","body":"การลงมติให้ใช้เสียงข้างมากของผู้เข้าประชุมที่มีสิทธิออกเสียง หากคะแนนเท่ากัน ให้ประธานในที่ประชุมออกเสียงเพิ่มอีกหนึ่งเสียงเป็นเสียงชี้ขาด ทั้งนี้มติที่มีผลต่อระเบียบ การเงิน ความปลอดภัย หรือชื่อเสียงของโรงเรียนต้องผ่านการรับทราบหรืออนุมัติตามสายงานก่อนดำเนินการ","keywords":["หมวด 10"],"sort_order":60},{"section_no":10,"clause_no":61,"title":"เลขานุการต้องจัดทำรายงานการประชุมและจัดเก็บไว้ในระบบเอกสารกลางของสภานักเรียน","body":"เลขานุการต้องจัดทำรายงานการประชุมและจัดเก็บไว้ในระบบเอกสารกลางของสภานักเรียน\nหมวด ๑๑\nกิจกรรมและการพัฒนาศักยภาพสภานักเรียน","keywords":["หมวด 10"],"sort_order":61},{"section_no":11,"clause_no":62,"title":"กิจกรรมที่เกี่ยวข้องกับสภานักเรียนให้แบ่งตามลักษณะการดำเนินงานเป็น ๒ ประเภท ดังต่อไปนี้","body":"กิจกรรมที่เกี่ยวข้องกับสภานักเรียนให้แบ่งตามลักษณะการดำเนินงานเป็น ๒ ประเภท ดังต่อไปนี้\n(๑) กิจกรรมที่โรงเรียน ฝ่ายงาน หรือครูที่ปรึกษาสภานักเรียนเป็นผู้รับผิดชอบหลักในการวางแผนและดำเนินการ โดยมีสมาชิกหรือว่าที่สมาชิกสภานักเรียนเป็นผู้เข้าร่วม ผู้รับการพัฒนา หรือผู้ปฏิบัติหน้าที่สตาฟตามที่ได้รับมอบหมาย\n(๒) กิจกรรมที่สภานักเรียนเป็นผู้ริเริ่ม เสนอ วางแผน และดำเนินการ ตลอดจนประเมินและสรุปผลกิจกรรม ภายใต้การให้คำปรึกษา การกำกับดูแล และการอนุมัติตามระบบของโรงเรียน","keywords":["หมวด 11"],"sort_order":62},{"section_no":11,"clause_no":63,"title":"กิจกรรมประเภทที่โรงเรียน ฝ่ายงาน หรือครูที่ปรึกษาสภานักเรียนเป็นผู้รับผิดชอบหลัก ตามข้อ ๖๒ (๑) ให้ประกอบด้วยกิจกรรมสำคัญดังต่อไปนี้","body":"กิจกรรมประเภทที่โรงเรียน ฝ่ายงาน หรือครูที่ปรึกษาสภานักเรียนเป็นผู้รับผิดชอบหลัก ตามข้อ ๖๒ (๑) ให้ประกอบด้วยกิจกรรมสำคัญดังต่อไปนี้\n(๑) กิจกรรมเสริมทักษะภาวะผู้นำ Youth Leadership For Azizstan (YLA)\n(๒) กิจกรรมเลือกตั้งประธานสภานักเรียน\n(๓) กิจกรรมเสริมทักษะการดำเนินการจัดกิจกรรมและการเขียนใบโครงการ\n(๔) กิจกรรมเสริมทักษะด้านการสื่อสารต่อหน้าสาธารณะ\n(๕) กิจกรรมเสริมทักษะด้านสื่อสร้างสรรค์\n(๖) กิจกรรมส่งเสริมคุณธรรมและจริยธรรม\n(๗) กิจกรรมส่งเสริมวัฒนธรรมและกิจกรรมสำคัญทางศาสนา\n(๘) กิจกรรมปรับพื้นฐานสำหรับนักเรียนระดับชั้นมัธยมศึกษาปีที่ ๑ และมัธยมศึกษาปีที่ ๔\n(๙) กิจกรรมอื่นที่โรงเรียน ฝ่ายงาน หรือครูที่ปรึกษาสภานักเรียนมอบหมายให้สภานักเรียนเข้าร่วม สนับสนุน หรือปฏิบัติหน้าที่สตาฟ","keywords":["หมวด 11"],"sort_order":63},{"section_no":11,"clause_no":64,"title":"กิจกรรม YLA เป็นกิจกรรมที่ครูที่ปรึกษาสภานักเรียนดำเนินการเพื่อพัฒนาและประเมินศักยภาพของว่าที่สมาชิกสภานักเรียน โดยให้การดำเนินงานเป็นไปตามกระบวนการสรรหาและพัฒนาภาวะผู้นำที่กำหน...","body":"กิจกรรม YLA เป็นกิจกรรมที่ครูที่ปรึกษาสภานักเรียนดำเนินการเพื่อพัฒนาและประเมินศักยภาพของว่าที่สมาชิกสภานักเรียน โดยให้การดำเนินงานเป็นไปตามกระบวนการสรรหาและพัฒนาภาวะผู้นำที่กำหนดไว้ในระเบียบนี้","keywords":["หมวด 11"],"sort_order":64},{"section_no":11,"clause_no":65,"title":"กิจกรรมเลือกตั้งประธานสภานักเรียนเป็นกิจกรรมที่ครูที่ปรึกษาสภานักเรียนเป็นผู้รับผิดชอบหลักในการจัดและควบคุมกระบวนการให้เป็นไปด้วยความเรียบร้อย เป็นธรรม และเหมาะสม โดยให้ว่าที่สม...","body":"กิจกรรมเลือกตั้งประธานสภานักเรียนเป็นกิจกรรมที่ครูที่ปรึกษาสภานักเรียนเป็นผู้รับผิดชอบหลักในการจัดและควบคุมกระบวนการให้เป็นไปด้วยความเรียบร้อย เป็นธรรม และเหมาะสม โดยให้ว่าที่สมาชิกสภานักเรียนที่ผ่านกระบวนการคัดเลือกจากกิจกรรม YLA ปฏิบัติหน้าที่สตาฟสนับสนุนการดำเนินงานตามที่ได้รับมอบหมาย ทั้งนี้ ผู้สมัครรับเลือกตั้งต้องไม่ปฏิบัติหน้าที่ในส่วนที่อาจก่อให้เกิดความได้เปรียบหรือผลประโยชน์ทับซ้อน","keywords":["หมวด 11"],"sort_order":65},{"section_no":11,"clause_no":66,"title":"กิจกรรมส่งเสริมวัฒนธรรมและกิจกรรมสำคัญทางศาสนา ตามข้อ ๖๓ (๗) ให้ฝ่ายวิชาการศาสนาหรือฝ่ายงานที่โรงเรียนกำหนดเป็นผู้รับผิดชอบหลัก โดยสภานักเรียนปฏิบัติหน้าที่สตาฟหรือสนับสนุนการดำ...","body":"กิจกรรมส่งเสริมวัฒนธรรมและกิจกรรมสำคัญทางศาสนา ตามข้อ ๖๓ (๗) ให้ฝ่ายวิชาการศาสนาหรือฝ่ายงานที่โรงเรียนกำหนดเป็นผู้รับผิดชอบหลัก โดยสภานักเรียนปฏิบัติหน้าที่สตาฟหรือสนับสนุนการดำเนินงานตามที่ได้รับมอบหมาย ซึ่งอาจประกอบด้วยกิจกรรมดังต่อไปนี้\n(๑) กิจกรรมอาซูรอสัมพันธ์\n(๒) กิจกรรมเมาลิดุนนบี\n(๓) กิจกรรมสลามรอมฎอน\n(๔) กิจกรรมสลามอีฎ","keywords":["หมวด 11"],"sort_order":66},{"section_no":11,"clause_no":67,"title":"ในกิจกรรมปรับพื้นฐานสำหรับนักเรียนระดับชั้นมัธยมศึกษาปีที่ ๑ และมัธยมศึกษาปีที่ ๔ ให้สภานักเรียนปฏิบัติหน้าที่สตาฟสนับสนุนการต้อนรับ การประสานงาน การอำนวยความสะดวก การจัดกิจกรรม...","body":"ในกิจกรรมปรับพื้นฐานสำหรับนักเรียนระดับชั้นมัธยมศึกษาปีที่ ๑ และมัธยมศึกษาปีที่ ๔ ให้สภานักเรียนปฏิบัติหน้าที่สตาฟสนับสนุนการต้อนรับ การประสานงาน การอำนวยความสะดวก การจัดกิจกรรม หรือภารกิจอื่นตามที่โรงเรียนหรือครูผู้รับผิดชอบมอบหมาย","keywords":["หมวด 11"],"sort_order":67},{"section_no":11,"clause_no":68,"title":"กิจกรรมที่สภานักเรียนเป็นผู้ริเริ่มและรับผิดชอบหลัก ตามข้อ ๖๒ (๒) ให้ประกอบด้วยกิจกรรมสำคัญดังต่อไปนี้","body":"กิจกรรมที่สภานักเรียนเป็นผู้ริเริ่มและรับผิดชอบหลัก ตามข้อ ๖๒ (๒) ให้ประกอบด้วยกิจกรรมสำคัญดังต่อไปนี้\n(๑) กิจกรรมแข่งขันฟุตซอลสานสัมพันธ์ภายใน ซึ่งให้สภานักเรียนชายเป็นผู้รับผิดชอบหลัก\n(๒) กิจกรรมกีฬาสานสัมพันธ์หอพัก ซึ่งให้สภานักเรียนหญิงเป็นผู้รับผิดชอบหลัก\n(๓) กิจกรรมอื่นที่สภานักเรียนเสนอและได้รับการพิจารณาอนุมัติจากโรงเรียน","keywords":["หมวด 11"],"sort_order":68},{"section_no":11,"clause_no":69,"title":"การดำเนินกิจกรรมที่สภานักเรียนเป็นผู้ริเริ่ม ให้สภานักเรียนรับผิดชอบกระบวนการตั้งแต่การกำหนดแนวคิดและวัตถุประสงค์ การเขียนและเสนอใบโครงการ การวางแผนงานและแบ่งหน้าที่ การกำหนดงบป...","body":"การดำเนินกิจกรรมที่สภานักเรียนเป็นผู้ริเริ่ม ให้สภานักเรียนรับผิดชอบกระบวนการตั้งแต่การกำหนดแนวคิดและวัตถุประสงค์ การเขียนและเสนอใบโครงการ การวางแผนงานและแบ่งหน้าที่ การกำหนดงบประมาณและทรัพยากร การประสานงาน การประชาสัมพันธ์ การดำเนินกิจกรรม การรวบรวมหลักฐาน ตลอดจนการประเมินและสรุปผลกิจกรรม ทั้งนี้ ต้องดำเนินการภายใต้การให้คำปรึกษาของครูที่ปรึกษาฝ่ายที่เกี่ยวข้องและตามขั้นตอนอนุมัติของโรงเรียน","keywords":["หมวด 11"],"sort_order":69},{"section_no":11,"clause_no":70,"title":"ครูที่ปรึกษาสภานักเรียนในกิจกรรมที่สภานักเรียนเป็นผู้ริเริ่ม มีหน้าที่ให้คำปรึกษา ตรวจสอบความเหมาะสม ความปลอดภัย งบประมาณ เอกสาร และการปฏิบัติตามระเบียบของโรงเรียน โดยควรส่งเสริ...","body":"ครูที่ปรึกษาสภานักเรียนในกิจกรรมที่สภานักเรียนเป็นผู้ริเริ่ม มีหน้าที่ให้คำปรึกษา ตรวจสอบความเหมาะสม ความปลอดภัย งบประมาณ เอกสาร และการปฏิบัติตามระเบียบของโรงเรียน โดยควรส่งเสริมให้นักเรียนเป็นผู้คิด วางแผน ตัดสินใจ และดำเนินงานด้วยตนเองตามศักยภาพ เว้นแต่เรื่องที่กฎหมาย ระเบียบ ความปลอดภัย หรือความรับผิดชอบของโรงเรียนกำหนดให้ครูหรือผู้บริหารเป็นผู้ดำเนินการ","keywords":["หมวด 11"],"sort_order":70},{"section_no":11,"clause_no":71,"title":"กิจกรรมใดที่มีลักษณะร่วมกันระหว่างโรงเรียน ฝ่ายงาน ครูที่ปรึกษา และสภานักเรียน หรือไม่อาจจำแนกผู้รับผิดชอบหลักได้ชัดเจน ให้หัวหน้าคณะครูที่ปรึกษาสภานักเรียนเป็นผู้กำหนดผู้รับผิด...","body":"กิจกรรมใดที่มีลักษณะร่วมกันระหว่างโรงเรียน ฝ่ายงาน ครูที่ปรึกษา และสภานักเรียน หรือไม่อาจจำแนกผู้รับผิดชอบหลักได้ชัดเจน ให้หัวหน้าคณะครูที่ปรึกษาสภานักเรียนเป็นผู้กำหนดผู้รับผิดชอบหลักและขอบเขตหน้าที่ของแต่ละฝ่ายก่อนเริ่มดำเนินกิจกรรม\nหมวด ๑๒\nแผนงาน โครงการ การเงิน เงินสำรอง เงินออม และทรัพย์สิน","keywords":["หมวด 11"],"sort_order":71},{"section_no":12,"clause_no":72,"title":"สภานักเรียนต้องจัดทำแผนงานหรือปฏิทินกิจกรรม และเสนอผ่านครูที่ปรึกษาฝ่ายที่เกี่ยวข้องเพื่อประสานการพิจารณาตามสายงานก่อนดำเนินการ","body":"สภานักเรียนต้องจัดทำแผนงานหรือปฏิทินกิจกรรม และเสนอผ่านครูที่ปรึกษาฝ่ายที่เกี่ยวข้องเพื่อประสานการพิจารณาตามสายงานก่อนดำเนินการ","keywords":["หมวด 12"],"sort_order":72},{"section_no":12,"clause_no":73,"title":"โครงการหรือกิจกรรมที่ใช้ชื่อโรงเรียน ใช้งบประมาณ ใช้สถานที่ ใช้ทรัพย์สิน มีการเดินทางออกนอกสถานศึกษา รับบริจาค เก็บเงิน ติดต่อหน่วยงานภายนอก หรือมีความเสี่ยงด้านความปลอดภัย ต้อง...","body":"โครงการหรือกิจกรรมที่ใช้ชื่อโรงเรียน ใช้งบประมาณ ใช้สถานที่ ใช้ทรัพย์สิน มีการเดินทางออกนอกสถานศึกษา รับบริจาค เก็บเงิน ติดต่อหน่วยงานภายนอก หรือมีความเสี่ยงด้านความปลอดภัย ต้องได้รับอนุมัติจากผู้มีอำนาจของโรงเรียนก่อนดำเนินการ","keywords":["หมวด 12"],"sort_order":73},{"section_no":12,"clause_no":74,"title":"การเงินของสภานักเรียนเป็นส่วนหนึ่งของระบบควบคุมภายในของโรงเรียน การรับเงิน เก็บรักษา เบิกจ่าย โอน หรือจัดซื้อ ต้องปฏิบัติตามระบบที่โรงเรียนกำหนดและมีหลักฐานครบถ้วน","body":"การเงินของสภานักเรียนเป็นส่วนหนึ่งของระบบควบคุมภายในของโรงเรียน การรับเงิน เก็บรักษา เบิกจ่าย โอน หรือจัดซื้อ ต้องปฏิบัติตามระบบที่โรงเรียนกำหนดและมีหลักฐานครบถ้วน","keywords":["หมวด 12"],"sort_order":74},{"section_no":12,"clause_no":75,"title":"ห้ามสมาชิกสภานักเรียนเปิดบัญชีหรือใช้ช่องทางการเงินส่วนบุคคลเพื่อกิจกรรมของสภานักเรียน เว้นแต่โรงเรียนอนุมัติเป็นกรณีเฉพาะและกำหนดวิธีตรวจสอบไว้อย่างชัดเจน","body":"ห้ามสมาชิกสภานักเรียนเปิดบัญชีหรือใช้ช่องทางการเงินส่วนบุคคลเพื่อกิจกรรมของสภานักเรียน เว้นแต่โรงเรียนอนุมัติเป็นกรณีเฉพาะและกำหนดวิธีตรวจสอบไว้อย่างชัดเจน","keywords":["หมวด 12"],"sort_order":75},{"section_no":12,"clause_no":76,"title":"ทรัพย์สิน วัสดุ อุปกรณ์ เอกสาร บัญชีผู้ใช้ ระบบออนไลน์ ฐานข้อมูล ไฟล์งาน สื่อประชาสัมพันธ์ หรือทรัพยากรดิจิทัลที่จัดทำเพื่อกิจการสภานักเรียน ให้ถือเป็นทรัพยากรสำหรับกิจการของโรง...","body":"ทรัพย์สิน วัสดุ อุปกรณ์ เอกสาร บัญชีผู้ใช้ ระบบออนไลน์ ฐานข้อมูล ไฟล์งาน สื่อประชาสัมพันธ์ หรือทรัพยากรดิจิทัลที่จัดทำเพื่อกิจการสภานักเรียน ให้ถือเป็นทรัพยากรสำหรับกิจการของโรงเรียนและต้องส่งมอบเมื่อพ้นหน้าที่","keywords":["หมวด 12"],"sort_order":76},{"section_no":12,"clause_no":77,"title":"การจัดทำชุดสภานักเรียนในแต่ละวาระ ให้ครูที่ปรึกษาสภานักเรียนภายใต้งานกิจกรรมนักเรียน ฝ่ายปกครอง ดำเนินการประสานการจัดซื้อผ้าที่ใช้ในการตัดชุดสภานักเรียน และอาจเรียกเก็บค่าผ้าชุด...","body":"การจัดทำชุดสภานักเรียนในแต่ละวาระ ให้ครูที่ปรึกษาสภานักเรียนภายใต้งานกิจกรรมนักเรียน ฝ่ายปกครอง ดำเนินการประสานการจัดซื้อผ้าที่ใช้ในการตัดชุดสภานักเรียน และอาจเรียกเก็บค่าผ้าชุดสภานักเรียนจากสมาชิกตามค่าใช้จ่ายจริงหรืออัตราที่โรงเรียนอนุมัติและประกาศให้ทราบล่วงหน้า โดยต้องแยกเงินส่วนนี้ออกจากเงินสำรองและเงินออม และมีหลักฐานการรับเงินและการใช้จ่ายที่ตรวจสอบได้","keywords":["หมวด 12"],"sort_order":77},{"section_no":12,"clause_no":78,"title":"ให้สมาชิกสภานักเรียนแต่ละคนวางเงินสำรองค่าใช้จ่ายในการปฏิบัติหน้าที่สภานักเรียนจำนวน ๕๐๐ บาทต่อวาระ ภายหลังได้รับการแต่งตั้งหรือภายในระยะเวลาที่โรงเรียนกำหนด ทั้งนี้ การรับและเก...","body":"ให้สมาชิกสภานักเรียนแต่ละคนวางเงินสำรองค่าใช้จ่ายในการปฏิบัติหน้าที่สภานักเรียนจำนวน ๕๐๐ บาทต่อวาระ ภายหลังได้รับการแต่งตั้งหรือภายในระยะเวลาที่โรงเรียนกำหนด ทั้งนี้ การรับและเก็บรักษาเงินต้องดำเนินการภายใต้ระบบการเงินหรือระบบควบคุมที่โรงเรียนกำหนด","keywords":["หมวด 12"],"sort_order":78},{"section_no":12,"clause_no":79,"title":"เงินสำรองตามข้อ ๗๘ ยังคงเป็นสิทธิของสมาชิกสภานักเรียนแต่ละคน ไม่ถือเป็นรายได้ส่วนกลางของสภานักเรียน และห้ามริบเงินสำรองเพื่อใช้เป็นบทลงโทษทางวินัย เว้นแต่เป็นการหักภาระค่าใช้จ่า...","body":"เงินสำรองตามข้อ ๗๘ ยังคงเป็นสิทธิของสมาชิกสภานักเรียนแต่ละคน ไม่ถือเป็นรายได้ส่วนกลางของสภานักเรียน และห้ามริบเงินสำรองเพื่อใช้เป็นบทลงโทษทางวินัย เว้นแต่เป็นการหักภาระค่าใช้จ่ายจริงที่เกิดขึ้นและเป็นไปตามเงื่อนไขในระเบียบนี้","keywords":["หมวด 12"],"sort_order":79},{"section_no":12,"clause_no":80,"title":"ในระหว่างวาระ หากมีค่าใช้จ่ายที่ได้รับอนุมัติ เช่น ค่าชุด ค่าอุปกรณ์ ค่าเดินทาง หรือค่าใช้จ่ายกิจกรรม และสมาชิกชำระภายในกำหนด เงินสำรองให้คงอยู่เต็มจำนวน หากสมาชิกไม่ชำระภายในกำ...","body":"ในระหว่างวาระ หากมีค่าใช้จ่ายที่ได้รับอนุมัติ เช่น ค่าชุด ค่าอุปกรณ์ ค่าเดินทาง หรือค่าใช้จ่ายกิจกรรม และสมาชิกชำระภายในกำหนด เงินสำรองให้คงอยู่เต็มจำนวน หากสมาชิกไม่ชำระภายในกำหนดหลังได้รับแจ้งแล้ว อาจหักจากเงินสำรองได้เฉพาะจำนวนค่าใช้จ่ายจริงที่ค้างชำระ โดยต้องบันทึกรายการหักและแจ้งยอดคงเหลือให้สมาชิกทราบ","keywords":["หมวด 12"],"sort_order":80},{"section_no":12,"clause_no":81,"title":"เมื่อสมาชิกครบวาระ ลาออก หรือพ้นจากสมาชิกสภานักเรียนไม่ว่าด้วยเหตุใด ให้ตรวจสอบภาระค่าใช้จ่ายที่เกิดขึ้นจริง หากไม่มีภาระค้างชำระให้คืนเงินสำรองเต็มจำนวน หากมีภาระค้างชำระให้หัก...","body":"เมื่อสมาชิกครบวาระ ลาออก หรือพ้นจากสมาชิกสภานักเรียนไม่ว่าด้วยเหตุใด ให้ตรวจสอบภาระค่าใช้จ่ายที่เกิดขึ้นจริง หากไม่มีภาระค้างชำระให้คืนเงินสำรองเต็มจำนวน หากมีภาระค้างชำระให้หักตามจำนวนจริงและคืนเงินส่วนที่เหลือ ทั้งนี้ การถูกให้พ้นจากสมาชิกสภานักเรียนไม่เป็นเหตุให้ริบเงินสำรองโดยอัตโนมัติ","keywords":["หมวด 12"],"sort_order":81},{"section_no":12,"clause_no":82,"title":"ให้สภานักเรียนมีระบบออมเงินรายบุคคลเพื่อส่งเสริมการวางแผนทางการเงินและเตรียมค่าใช้จ่ายสำหรับกิจกรรมปลายวาระ โดยเฉพาะกิจกรรมทัศนศึกษาหรือกิจกรรมตอบแทนสมาชิกสภานักเรียนที่กำลังจะส...","body":"ให้สภานักเรียนมีระบบออมเงินรายบุคคลเพื่อส่งเสริมการวางแผนทางการเงินและเตรียมค่าใช้จ่ายสำหรับกิจกรรมปลายวาระ โดยเฉพาะกิจกรรมทัศนศึกษาหรือกิจกรรมตอบแทนสมาชิกสภานักเรียนที่กำลังจะสิ้นสุดวาระ ซึ่งโรงเรียนอาจสนับสนุนค่าใช้จ่ายส่วนใหญ่และเรียกเก็บส่วนเพิ่มเติมตามค่าใช้จ่ายที่เกิดขึ้นจริง ทั้งนี้ ให้กำหนดเป้าหมายการออมขั้นต่ำสัปดาห์ละ ๒๐ บาทต่อคน หรือตามอัตราที่โรงเรียนประกาศในแต่ละวาระ","keywords":["หมวด 12"],"sort_order":82},{"section_no":12,"clause_no":83,"title":"เงินออมตามข้อ ๘๒ เป็นเงินของสมาชิกแต่ละคนโดยเฉพาะ ต้องจัดทำบัญชีหรือทะเบียนยอดออมรายบุคคล แยกจากเงินสำรอง เงินกิจกรรม และเงินส่วนกลางของสภานักเรียน และห้ามนำเงินออมของสมาชิกคนหน...","body":"เงินออมตามข้อ ๘๒ เป็นเงินของสมาชิกแต่ละคนโดยเฉพาะ ต้องจัดทำบัญชีหรือทะเบียนยอดออมรายบุคคล แยกจากเงินสำรอง เงินกิจกรรม และเงินส่วนกลางของสภานักเรียน และห้ามนำเงินออมของสมาชิกคนหนึ่งไปใช้เป็นค่าใช้จ่ายของสมาชิกคนอื่นโดยไม่ได้รับความยินยอม","keywords":["หมวด 12"],"sort_order":83},{"section_no":12,"clause_no":84,"title":"กรณีสมาชิกไม่ได้ออมตามกำหนดในสัปดาห์ใด ให้ถือเป็นยอดออมค้างสะสม มิให้ถือเป็นความผิดทางวินัยหรือค่าปรับ และควรเปิดโอกาสให้สมาชิกชำระเพิ่มเติมภายหลังได้ หากได้แจ้งเงื่อนไขและได้รั...","body":"กรณีสมาชิกไม่ได้ออมตามกำหนดในสัปดาห์ใด ให้ถือเป็นยอดออมค้างสะสม มิให้ถือเป็นความผิดทางวินัยหรือค่าปรับ และควรเปิดโอกาสให้สมาชิกชำระเพิ่มเติมภายหลังได้ หากได้แจ้งเงื่อนไขและได้รับความยินยอมจากสมาชิกและผู้ปกครองไว้ล่วงหน้า โรงเรียนอาจโอนเงินจากเงินสำรองของสมาชิกจำนวนเท่ากับยอดออมที่ค้างไปบันทึกเป็นเงินออมของสมาชิกคนนั้นได้ โดยให้ถือเป็นการโอนระหว่างยอดเงินของสมาชิก มิใช่การหักเป็นค่าใช้จ่าย และต้องแสดงรายการดังกล่าวในบัญชีรายบุคคลอย่างชัดเจน","keywords":["หมวด 12"],"sort_order":84},{"section_no":12,"clause_no":85,"title":"เมื่อถึงกำหนดกิจกรรมปลายวาระ ให้หักค่าใช้จ่ายที่สมาชิกต้องร่วมรับผิดชอบตามจริงจากยอดเงินออมของสมาชิกแต่ละคน หากยอดเงินออมไม่เพียงพอ ให้แจ้งจำนวนส่วนต่างที่ต้องชำระเพิ่มเติมล่วงห...","body":"เมื่อถึงกำหนดกิจกรรมปลายวาระ ให้หักค่าใช้จ่ายที่สมาชิกต้องร่วมรับผิดชอบตามจริงจากยอดเงินออมของสมาชิกแต่ละคน หากยอดเงินออมไม่เพียงพอ ให้แจ้งจำนวนส่วนต่างที่ต้องชำระเพิ่มเติมล่วงหน้า หากมียอดเงินออมคงเหลือหลังเสร็จสิ้นกิจกรรมและไม่มีภาระผูกพันอื่น ให้คืนยอดคงเหลือแก่สมาชิกตามขั้นตอนที่โรงเรียนกำหนด","keywords":["หมวด 12"],"sort_order":85},{"section_no":12,"clause_no":86,"title":"สมาชิกที่ไม่ได้เข้าร่วมกิจกรรมปลายวาระ ลาออก หรือพ้นจากสมาชิกสภานักเรียนก่อนถึงกำหนดกิจกรรม มีสิทธิได้รับเงินออมคงเหลือคืน เว้นแต่มีค่าใช้จ่ายที่เกิดขึ้นจริงและไม่สามารถขอคืนได้...","body":"สมาชิกที่ไม่ได้เข้าร่วมกิจกรรมปลายวาระ ลาออก หรือพ้นจากสมาชิกสภานักเรียนก่อนถึงกำหนดกิจกรรม มีสิทธิได้รับเงินออมคงเหลือคืน เว้นแต่มีค่าใช้จ่ายที่เกิดขึ้นจริงและไม่สามารถขอคืนได้ซึ่งจัดเตรียมไว้เฉพาะสำหรับสมาชิกคนนั้น โดยการหักเงินดังกล่าวต้องมีหลักฐานและแจ้งให้สมาชิกหรือผู้ปกครองทราบ","keywords":["หมวด 12"],"sort_order":86},{"section_no":12,"clause_no":87,"title":"การรับเงินค่าผ้าชุดสภานักเรียน เงินสำรอง และเงินออม ต้องมีหลักฐานการรับเงิน มีทะเบียนรายบุคคล และสามารถตรวจสอบยอดได้ ครูที่ปรึกษาหรือผู้ได้รับมอบหมายต้องรายงานยอดเงินตามระยะเวลา...","body":"การรับเงินค่าผ้าชุดสภานักเรียน เงินสำรอง และเงินออม ต้องมีหลักฐานการรับเงิน มีทะเบียนรายบุคคล และสามารถตรวจสอบยอดได้ ครูที่ปรึกษาหรือผู้ได้รับมอบหมายต้องรายงานยอดเงินตามระยะเวลาที่เหมาะสม และไม่ควรเก็บรักษาเงินดังกล่าวไว้ในบัญชีส่วนบุคคล เว้นแต่โรงเรียนอนุมัติเป็นกรณีเฉพาะพร้อมกำหนดระบบตรวจสอบ","keywords":["หมวด 12"],"sort_order":87},{"section_no":12,"clause_no":88,"title":"การเรียกเก็บเงินที่มีลักษณะเป็นค่าใช้จ่ายบังคับจากสมาชิกสภานักเรียน เช่น ค่าผ้าชุดสภานักเรียนหรือค่าใช้จ่ายอื่น ต้องได้รับอนุมัติตามระบบของโรงเรียน และในกรณีที่เข้าลักษณะค่าธรรม...","body":"การเรียกเก็บเงินที่มีลักษณะเป็นค่าใช้จ่ายบังคับจากสมาชิกสภานักเรียน เช่น ค่าผ้าชุดสภานักเรียนหรือค่าใช้จ่ายอื่น ต้องได้รับอนุมัติตามระบบของโรงเรียน และในกรณีที่เข้าลักษณะค่าธรรมเนียมอื่นของโรงเรียนเอกชน ให้ดำเนินการตามกฎหมาย ประกาศ และหลักเกณฑ์ของสำนักงานคณะกรรมการส่งเสริมการศึกษาเอกชนที่ใช้บังคับ รวมทั้งผ่านความเห็นชอบของคณะกรรมการบริหารโรงเรียนก่อนประกาศเรียกเก็บ สำหรับระบบเงินออม โรงเรียนต้องแจ้งวัตถุประสงค์ อัตรา วิธีเก็บรักษา วิธีใช้ และเงื่อนไขการคืนเงินให้สมาชิกและผู้ปกครองทราบล่วงหน้า และควรมีแนวทางผ่อนผันหรือช่วยเหลือกรณีสมาชิกมีข้อจำกัดด้านเศรษฐกิจ เพื่อมิให้เป็นอุปสรรคต่อการปฏิบัติหน้าที่สภานักเรียน\nหมวด ๑๓\nครูที่ปรึกษาสภานักเรียนและการกำกับดูแล","keywords":["หมวด 12"],"sort_order":88},{"section_no":13,"clause_no":89,"title":"สภานักเรียนอยู่ภายใต้การกำกับของงานกิจกรรมนักเรียน ฝ่ายปกครอง โดยให้หัวหน้าฝ่ายปกครองทำหน้าที่หัวหน้าคณะครูที่ปรึกษาสภานักเรียน และเป็นผู้กำกับภาพรวมของการดำเนินงาน","body":"สภานักเรียนอยู่ภายใต้การกำกับของงานกิจกรรมนักเรียน ฝ่ายปกครอง โดยให้หัวหน้าฝ่ายปกครองทำหน้าที่หัวหน้าคณะครูที่ปรึกษาสภานักเรียน และเป็นผู้กำกับภาพรวมของการดำเนินงาน","keywords":["หมวด 13"],"sort_order":89},{"section_no":13,"clause_no":90,"title":"ให้โรงเรียนแต่งตั้งครูที่ปรึกษาสภานักเรียนตามจำนวนที่เหมาะสม และกำหนดให้ครูที่ปรึกษาแต่ละคนรับผิดชอบฝ่าย ภารกิจ หรือกลุ่มงานตามที่ได้รับมอบหมาย","body":"ให้โรงเรียนแต่งตั้งครูที่ปรึกษาสภานักเรียนตามจำนวนที่เหมาะสม และกำหนดให้ครูที่ปรึกษาแต่ละคนรับผิดชอบฝ่าย ภารกิจ หรือกลุ่มงานตามที่ได้รับมอบหมาย","keywords":["หมวด 13"],"sort_order":90},{"section_no":13,"clause_no":91,"title":"ครูที่ปรึกษาสภานักเรียนมีหน้าที่ดังต่อไปนี้","body":"ครูที่ปรึกษาสภานักเรียนมีหน้าที่ดังต่อไปนี้\n(๑) ให้คำปรึกษาและสนับสนุนให้นักเรียนคิด วางแผน และดำเนินงานด้วยตนเอง\n(๒) กำกับให้การดำเนินงานของฝ่ายที่รับผิดชอบเป็นไปตามระเบียบโรงเรียน หลักการศาสนา และหลักความปลอดภัย\n(๓) ประสานงานกับหัวหน้าคณะครูที่ปรึกษาสภานักเรียน ครู ฝ่ายงาน ผู้ปกครอง และผู้เกี่ยวข้องตามความจำเป็น\n(๔) ตรวจสอบและให้คำแนะนำด้านโครงการ เอกสาร การเงิน ความเสี่ยง การประชาสัมพันธ์ และการดำเนินกิจกรรม\n(๕) ติดตามการปฏิบัติงานของหัวหน้าฝ่ายและสมาชิกในฝ่ายที่รับผิดชอบ\n(๖) รายงานปัญหา อุปสรรค หรือกรณีที่เกินขอบเขตการตัดสินใจต่อหัวหน้าคณะครูที่ปรึกษาสภานักเรียน\n(๗) สนับสนุนการประเมินผลและการส่งมอบงานระหว่างวาระ","keywords":["หมวด 13"],"sort_order":91},{"section_no":13,"clause_no":92,"title":"หัวหน้าคณะครูที่ปรึกษาสภานักเรียนมีหน้าที่กำกับภาพรวมของงานสภานักเรียน มอบหมายและประสานงานครูที่ปรึกษา พิจารณาเรื่องที่เกี่ยวข้องกับหลายฝ่ายหรือเกินขอบเขตของครูที่ปรึกษาฝ่ายใดฝ่...","body":"หัวหน้าคณะครูที่ปรึกษาสภานักเรียนมีหน้าที่กำกับภาพรวมของงานสภานักเรียน มอบหมายและประสานงานครูที่ปรึกษา พิจารณาเรื่องที่เกี่ยวข้องกับหลายฝ่ายหรือเกินขอบเขตของครูที่ปรึกษาฝ่ายใดฝ่ายหนึ่ง และเสนอเรื่องต่อผู้บริหารโรงเรียนตามสายงาน","keywords":["หมวด 13"],"sort_order":92},{"section_no":13,"clause_no":93,"title":"ครูที่ปรึกษาควรทำหน้าที่เป็นผู้ให้คำปรึกษาและผู้กำกับดูแล ไม่ดำเนินงานแทนนักเรียนในทุกเรื่อง เว้นแต่เป็นเรื่องที่เกี่ยวข้องกับกฎหมาย ความปลอดภัย การเงิน อำนาจของโรงเรียน หรือเรื...","body":"ครูที่ปรึกษาควรทำหน้าที่เป็นผู้ให้คำปรึกษาและผู้กำกับดูแล ไม่ดำเนินงานแทนนักเรียนในทุกเรื่อง เว้นแต่เป็นเรื่องที่เกี่ยวข้องกับกฎหมาย ความปลอดภัย การเงิน อำนาจของโรงเรียน หรือเรื่องที่นักเรียนไม่มีอำนาจดำเนินการเอง","keywords":["หมวด 13"],"sort_order":93},{"section_no":13,"clause_no":94,"title":"ผู้บริหารโรงเรียนหรือหัวหน้าฝ่ายปกครองตามอำนาจหน้าที่ อาจสั่งระงับ แก้ไข หรือยุติกิจกรรมของสภานักเรียนเมื่อเห็นว่าขัดต่อระเบียบ หลักการศาสนา ความปลอดภัย ประโยชน์ของนักเรียน หรือ...","body":"ผู้บริหารโรงเรียนหรือหัวหน้าฝ่ายปกครองตามอำนาจหน้าที่ อาจสั่งระงับ แก้ไข หรือยุติกิจกรรมของสภานักเรียนเมื่อเห็นว่าขัดต่อระเบียบ หลักการศาสนา ความปลอดภัย ประโยชน์ของนักเรียน หรือชื่อเสียงของโรงเรียน\nหมวด ๑๔\nเอกสาร ข้อมูล การประชาสัมพันธ์ และความโปร่งใส","keywords":["หมวด 13"],"sort_order":94},{"section_no":14,"clause_no":95,"title":"สภานักเรียนต้องมีระบบจัดเก็บเอกสารอย่างน้อย ได้แก่ คำสั่งแต่งตั้ง โครงสร้างและรายชื่อสมาชิก แผนงาน รายงานการประชุม โครงการ รายงานผล เอกสารการเงิน ทะเบียนทรัพย์สิน ทะเบียนการเข้า...","body":"สภานักเรียนต้องมีระบบจัดเก็บเอกสารอย่างน้อย ได้แก่ คำสั่งแต่งตั้ง โครงสร้างและรายชื่อสมาชิก แผนงาน รายงานการประชุม โครงการ รายงานผล เอกสารการเงิน ทะเบียนทรัพย์สิน ทะเบียนการเข้าร่วมประชุม กิจกรรมและภารกิจ แบบประเมินผลการปฏิบัติหน้าที่ แบบติดตามการขาดและข้อตกลงปรับปรุง ทะเบียนการออกเกียรติบัตรหรือหนังสือรับรอง และเอกสารส่งมอบงาน","keywords":["หมวด 14"],"sort_order":95},{"section_no":14,"clause_no":96,"title":"เอกสารและข้อมูลดิจิทัลต้องจัดเก็บในช่องทางที่โรงเรียนกำหนดหรือสามารถส่งมอบให้โรงเรียนได้ ห้ามผูกระบบงานสำคัญไว้กับบัญชีส่วนตัวของนักเรียนเพียงบุคคลเดียวโดยไม่มีผู้ดูแลสำรอง","body":"เอกสารและข้อมูลดิจิทัลต้องจัดเก็บในช่องทางที่โรงเรียนกำหนดหรือสามารถส่งมอบให้โรงเรียนได้ ห้ามผูกระบบงานสำคัญไว้กับบัญชีส่วนตัวของนักเรียนเพียงบุคคลเดียวโดยไม่มีผู้ดูแลสำรอง","keywords":["หมวด 14"],"sort_order":96},{"section_no":14,"clause_no":97,"title":"การเผยแพร่ภาพ ชื่อ ข้อมูลส่วนบุคคล ผลงาน หรือข้อมูลกิจกรรมของนักเรียน ต้องคำนึงถึงความเป็นส่วนตัว ความเหมาะสม ความปลอดภัย และแนวปฏิบัติของโรงเรียน","body":"การเผยแพร่ภาพ ชื่อ ข้อมูลส่วนบุคคล ผลงาน หรือข้อมูลกิจกรรมของนักเรียน ต้องคำนึงถึงความเป็นส่วนตัว ความเหมาะสม ความปลอดภัย และแนวปฏิบัติของโรงเรียน","keywords":["หมวด 14"],"sort_order":97},{"section_no":14,"clause_no":98,"title":"สื่อประชาสัมพันธ์ที่ใช้ชื่อ ตราสัญลักษณ์ หรือเผยแพร่ในนามโรงเรียนหรือสภานักเรียน ต้องผ่านการตรวจสอบตามระบบที่โรงเรียนกำหนด","body":"สื่อประชาสัมพันธ์ที่ใช้ชื่อ ตราสัญลักษณ์ หรือเผยแพร่ในนามโรงเรียนหรือสภานักเรียน ต้องผ่านการตรวจสอบตามระบบที่โรงเรียนกำหนด\nหมวด ๑๕\nการประเมินการปฏิบัติหน้าที่ การเข้าร่วม และการรับรองผลการปฏิบัติหน้าที่","keywords":["หมวด 14"],"sort_order":98},{"section_no":15,"clause_no":99,"title":"ให้มีการประเมินผลการปฏิบัติหน้าที่ของสมาชิกสภานักเรียนอย่างเป็นระบบ อย่างน้อยภาคเรียนละ ๑ ครั้ง และให้มีการประเมินสรุปก่อนสิ้นสุดวาระ โดยครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบฝ่ายเ...","body":"ให้มีการประเมินผลการปฏิบัติหน้าที่ของสมาชิกสภานักเรียนอย่างเป็นระบบ อย่างน้อยภาคเรียนละ ๑ ครั้ง และให้มีการประเมินสรุปก่อนสิ้นสุดวาระ โดยครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบฝ่ายเป็นผู้ประเมินหลัก และอาจใช้ข้อมูลจากหัวหน้าฝ่าย ประธานสภานักเรียน แบบประเมินตนเอง หลักฐานการปฏิบัติงาน และข้อมูลจากระบบของโรงเรียนประกอบการพิจารณา ทั้งนี้ ผลการประเมินให้ใช้เพื่อการพัฒนา การติดตามการปฏิบัติหน้าที่ การรับรองผลการปฏิบัติงาน และการพิจารณาสิทธิได้รับเกียรติบัตรหรือหนังสือรับรอง","keywords":["หมวด 15"],"sort_order":99},{"section_no":15,"clause_no":100,"title":"การประเมินผลการปฏิบัติหน้าที่ให้พิจารณาอย่างน้อยในด้านดังต่อไปนี้","body":"การประเมินผลการปฏิบัติหน้าที่ให้พิจารณาอย่างน้อยในด้านดังต่อไปนี้\n(๑) ความรับผิดชอบและการปฏิบัติงานตามหน้าที่หรือภารกิจที่ได้รับมอบหมาย ๒๕ คะแนน\n(๒) การเข้าร่วมประชุม กิจกรรม และภารกิจ รวมถึงความตรงต่อเวลา ๒๐ คะแนน\n(๓) การทำงานร่วมกับผู้อื่น การสื่อสาร การประสานงาน และการเคารพบทบาทของแต่ละฝ่าย ๑๕ คะแนน\n(๔) ความคิดริเริ่ม การแก้ปัญหา การวางแผน และการพัฒนางาน ๑๕ คะแนน\n(๕) วินัย คุณธรรม จริยธรรม การเป็นแบบอย่างที่ดี และการปฏิบัติตามระเบียบของโรงเรียนและหลักการศาสนา ๑๕ คะแนน\n(๖) การจัดทำ ส่งมอบ และเก็บรักษาเอกสาร ทรัพย์สิน ข้อมูล งานค้าง หรือทรัพยากรที่อยู่ในความรับผิดชอบ ๑๐ คะแนน\nให้ใช้รายละเอียดและคำอธิบายเกณฑ์ตามแบบประเมินที่โรงเรียนกำหนด โดยคะแนนรวมคิดเป็น ๑๐๐ คะแนน และถือว่าผ่านการประเมินเมื่อได้คะแนนรวมไม่น้อยกว่า ๗๐ คะแนน เว้นแต่โรงเรียนประกาศเกณฑ์ที่สูงกว่าสำหรับวาระนั้น","keywords":["หมวด 15"],"sort_order":100},{"section_no":15,"clause_no":101,"title":"สมาชิกสภานักเรียนต้องเข้าร่วมการประชุม กิจกรรม และภารกิจที่ได้รับมอบหมายอย่างสม่ำเสมอ ให้มีการบันทึกสถานะอย่างน้อยเป็น “เข้าร่วม” “มาสาย” “ลาโดยได้รับอนุญาต” และ “ขาดโดยไม่มีเหต...","body":"สมาชิกสภานักเรียนต้องเข้าร่วมการประชุม กิจกรรม และภารกิจที่ได้รับมอบหมายอย่างสม่ำเสมอ ให้มีการบันทึกสถานะอย่างน้อยเป็น “เข้าร่วม” “มาสาย” “ลาโดยได้รับอนุญาต” และ “ขาดโดยไม่มีเหตุอันควร” ในระบบหรือแบบบันทึกที่โรงเรียนกำหนด โดยให้แจ้งกำหนดการหรือภารกิจแก่สมาชิกตามสมควรล่วงหน้า เว้นแต่เป็นเหตุเร่งด่วนหรือภารกิจเฉพาะหน้า","keywords":["หมวด 15"],"sort_order":101},{"section_no":15,"clause_no":102,"title":"การลาเนื่องจากเจ็บป่วย ภารกิจที่โรงเรียนมอบหมาย เหตุจำเป็นเกี่ยวกับครอบครัว เหตุสุดวิสัย หรือเหตุอื่นที่ครูที่ปรึกษาสภานักเรียนเห็นสมควร เมื่อได้แจ้งและได้รับอนุญาตตามระบบ ไม่ให...","body":"การลาเนื่องจากเจ็บป่วย ภารกิจที่โรงเรียนมอบหมาย เหตุจำเป็นเกี่ยวกับครอบครัว เหตุสุดวิสัย หรือเหตุอื่นที่ครูที่ปรึกษาสภานักเรียนเห็นสมควร เมื่อได้แจ้งและได้รับอนุญาตตามระบบ ไม่ให้ถือเป็นการขาดโดยไม่มีเหตุอันควร หากไม่สามารถแจ้งล่วงหน้าได้เนื่องจากเหตุฉุกเฉิน ให้แจ้งพร้อมเหตุผลและหลักฐานเท่าที่จำเป็นภายใน ๓ วันทำการของโรงเรียนหลังจากกลับมาปฏิบัติหน้าที่ เว้นแต่มีเหตุจำเป็นที่ครูที่ปรึกษาเห็นสมควรขยายเวลา","keywords":["หมวด 15"],"sort_order":102},{"section_no":15,"clause_no":103,"title":"กรณีสมาชิกขาดการประชุม กิจกรรม หรือภารกิจที่ได้รับมอบหมายโดยไม่มีเหตุอันควร ให้ดำเนินการตามลำดับดังต่อไปนี้","body":"กรณีสมาชิกขาดการประชุม กิจกรรม หรือภารกิจที่ได้รับมอบหมายโดยไม่มีเหตุอันควร ให้ดำเนินการตามลำดับดังต่อไปนี้\n(๑) ครั้งที่ ๑ ให้ครูที่ปรึกษาหรือผู้รับผิดชอบแจ้งเตือนและบันทึกเหตุไว้ในระบบหรือแบบติดตาม\n(๒) ครั้งที่ ๒ ภายในภาคเรียนเดียวกัน ให้มีหนังสือหรือบันทึกแจ้งเตือน และให้สมาชิกชี้แจงเหตุผลต่อครูที่ปรึกษาผู้รับผิดชอบ\n(๓) ครั้งที่ ๓ ภายในภาคเรียนเดียวกัน ให้จัดทำข้อตกลงปรับปรุงการปฏิบัติหน้าที่เป็นลายลักษณ์อักษร กำหนดระยะเวลาติดตามไม่น้อยกว่า ๓๐ วัน และอาจแจ้งผู้ปกครองหรือครูที่ปรึกษาสามัญตามความเหมาะสม\n(๔) ภายหลังจัดทำข้อตกลงตาม (๓) หากสมาชิกขาดโดยไม่มีเหตุอันควรอีก หรือเมื่อสิ้นภาคเรียนมีอัตราการเข้าร่วมต่ำกว่าร้อยละ ๘๐ ของการประชุม กิจกรรม และภารกิจที่สมาชิกมีหน้าที่ต้องเข้าร่วม โดยไม่นับรายการที่ลาและได้รับอนุญาต ให้ครูที่ปรึกษาเสนอหัวหน้าคณะครูที่ปรึกษาสภานักเรียนพิจารณาความเหมาะสมในการพักหน้าที่ ปรับบทบาท หรือดำเนินการตามข้อ ๓๕ และข้อ ๔๗ แล้วแต่กรณี","keywords":["หมวด 15"],"sort_order":103},{"section_no":15,"clause_no":104,"title":"การมาสายหรือออกจากกิจกรรมก่อนเวลาให้บันทึกไว้เพื่อใช้ประกอบการประเมินด้านความรับผิดชอบ หากสมาชิกเข้าร่วมไม่ถึงกึ่งหนึ่งของระยะเวลาการประชุม กิจกรรม หรือภารกิจโดยไม่มีเหตุอันควร ...","body":"การมาสายหรือออกจากกิจกรรมก่อนเวลาให้บันทึกไว้เพื่อใช้ประกอบการประเมินด้านความรับผิดชอบ หากสมาชิกเข้าร่วมไม่ถึงกึ่งหนึ่งของระยะเวลาการประชุม กิจกรรม หรือภารกิจโดยไม่มีเหตุอันควร อาจบันทึกเป็นการขาดหนึ่งครั้งได้ตามดุลพินิจของครูที่ปรึกษาผู้รับผิดชอบ โดยต้องใช้หลักเกณฑ์เดียวกันกับสมาชิกที่อยู่ในสถานการณ์เดียวกัน","keywords":["หมวด 15"],"sort_order":104},{"section_no":15,"clause_no":105,"title":"สมาชิกที่มีสิทธิได้รับ “เกียรติบัตรรับรองการปฏิบัติหน้าที่สภานักเรียน” ต้องมีคุณสมบัติครบถ้วนดังต่อไปนี้","body":"สมาชิกที่มีสิทธิได้รับ “เกียรติบัตรรับรองการปฏิบัติหน้าที่สภานักเรียน” ต้องมีคุณสมบัติครบถ้วนดังต่อไปนี้\n(๑) มีชื่ออยู่ในคำสั่งแต่งตั้งคณะกรรมการสภานักเรียนของโรงเรียน\n(๒) ปฏิบัติหน้าที่จนสิ้นสุดวาระ หรือพ้นหน้าที่ก่อนสิ้นสุดวาระด้วยเหตุจำเป็นที่โรงเรียนรับรองและเห็นสมควรให้เทียบเท่า\n(๓) มีอัตราการเข้าร่วมประชุม กิจกรรม และภารกิจที่มีหน้าที่ต้องเข้าร่วมไม่น้อยกว่าร้อยละ ๘๐ โดยไม่นับรายการที่ลาและได้รับอนุญาต\n(๔) ผ่านการประเมินผลการปฏิบัติหน้าที่ตามข้อ ๑๐๐\n(๕) ไม่ถูกให้พ้นจากตำแหน่งเนื่องจากความผิดร้ายแรงหรือการกระทำที่ทำให้ขาดคุณสมบัติในการเป็นแบบอย่างที่ดี\n(๖) ดำเนินการส่งมอบงาน เอกสาร ทรัพย์สิน เงิน ข้อมูล งานค้าง ระบบดิจิทัล หรือสิทธิการเข้าถึงที่อยู่ในความรับผิดชอบของตนให้เรียบร้อย\n(๗) ไม่มีภาระทางการเงิน ทรัพย์สิน หรือเอกสารของสภานักเรียนที่ต้องส่งคืนหรือชี้แจงค้างอยู่โดยไม่มีเหตุอันสมควร","keywords":["หมวด 15"],"sort_order":105},{"section_no":15,"clause_no":106,"title":"สมาชิกที่เคยปฏิบัติหน้าที่จริงแต่ไม่ครบเกณฑ์สำหรับเกียรติบัตรตามข้อ ๑๐๕ เนื่องจากลาออก ย้ายสถานศึกษา เจ็บป่วยระยะยาว เหตุจำเป็น หรือเหตุอื่นที่ไม่ใช่ความผิดร้ายแรง โรงเรียนอาจออ...","body":"สมาชิกที่เคยปฏิบัติหน้าที่จริงแต่ไม่ครบเกณฑ์สำหรับเกียรติบัตรตามข้อ ๑๐๕ เนื่องจากลาออก ย้ายสถานศึกษา เจ็บป่วยระยะยาว เหตุจำเป็น หรือเหตุอื่นที่ไม่ใช่ความผิดร้ายแรง โรงเรียนอาจออก “หนังสือรับรองการเข้าร่วมและการปฏิบัติหน้าที่” โดยระบุช่วงเวลา ตำแหน่ง และลักษณะงานตามข้อเท็จจริงแทนเกียรติบัตรรับรองการปฏิบัติหน้าที่ครบวาระ กรณีสมาชิกมีการลาโดยได้รับอนุญาตเป็นจำนวนมากจนไม่มีหลักฐานการปฏิบัติหน้าที่จริงเพียงพอสำหรับการรับรองการปฏิบัติหน้าที่ครบวาระ ให้พิจารณาออกหนังสือรับรองตามข้อเท็จจริงแทน ทั้งนี้ ผู้ที่ถูกให้พ้นจากตำแหน่งเนื่องจากความผิดร้ายแรงไม่มีสิทธิได้รับเกียรติบัตรรับรองการปฏิบัติหน้าที่ครบวาระ","keywords":["หมวด 15"],"sort_order":106},{"section_no":15,"clause_no":107,"title":"ก่อนออกเกียรติบัตรหรือหนังสือรับรอง ให้ครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบตรวจสอบข้อมูลการเข้าร่วม ผลการประเมิน สถานะวินัย การส่งมอบงาน และภาระค้างทั้งหมด แล้วเสนอหัวหน้าคณะครูท...","body":"ก่อนออกเกียรติบัตรหรือหนังสือรับรอง ให้ครูที่ปรึกษาสภานักเรียนผู้รับผิดชอบตรวจสอบข้อมูลการเข้าร่วม ผลการประเมิน สถานะวินัย การส่งมอบงาน และภาระค้างทั้งหมด แล้วเสนอหัวหน้าคณะครูที่ปรึกษาสภานักเรียนรับรองรายชื่อ ผู้มีอำนาจของโรงเรียนหรือผู้ที่ได้รับมอบหมายเป็นผู้ลงนามในเกียรติบัตรหรือหนังสือรับรอง และให้จัดเก็บข้อมูลการออกเอกสารไว้ในระบบหรือทะเบียนกลางของสภานักเรียน","keywords":["หมวด 15"],"sort_order":107},{"section_no":15,"clause_no":108,"title":"เกณฑ์การประเมิน การบันทึกการเข้าร่วม การลา การติดตามการขาด และการรับรองสิทธิได้รับเกียรติบัตรตามหมวดนี้ ให้ใช้แบบฟอร์มหรือระบบที่โรงเรียนกำหนด และต้องสามารถตรวจสอบย้อนหลังได้ ห้...","body":"เกณฑ์การประเมิน การบันทึกการเข้าร่วม การลา การติดตามการขาด และการรับรองสิทธิได้รับเกียรติบัตรตามหมวดนี้ ให้ใช้แบบฟอร์มหรือระบบที่โรงเรียนกำหนด และต้องสามารถตรวจสอบย้อนหลังได้ ห้ามแก้ไขข้อมูลย้อนหลังโดยไม่มีผู้รับผิดชอบ เหตุผล และร่องรอยการแก้ไขที่ตรวจสอบได้\nหมวด ๑๖\nการส่งมอบงาน การแก้ไขระเบียบ และบทเฉพาะกาล","keywords":["หมวด 15"],"sort_order":108},{"section_no":16,"clause_no":109,"title":"ก่อนสิ้นสุดวาระ ให้คณะกรรมการสภานักเรียนจัดทำการส่งมอบงานแก่คณะกรรมการชุดใหม่หรือผู้ที่โรงเรียนกำหนด โดยอย่างน้อยต้องส่งมอบเอกสาร ทรัพย์สิน ข้อมูลโครงการ งานค้าง ระบบดิจิทัล และ...","body":"ก่อนสิ้นสุดวาระ ให้คณะกรรมการสภานักเรียนจัดทำการส่งมอบงานแก่คณะกรรมการชุดใหม่หรือผู้ที่โรงเรียนกำหนด โดยอย่างน้อยต้องส่งมอบเอกสาร ทรัพย์สิน ข้อมูลโครงการ งานค้าง ระบบดิจิทัล และสิทธิการเข้าถึงที่จำเป็น","keywords":["หมวด 16"],"sort_order":109},{"section_no":16,"clause_no":110,"title":"ให้มีการประชุมส่งมอบงานอย่างเป็นทางการ และจัดทำบันทึกส่งมอบโดยมีผู้ส่งมอบ ผู้รับมอบ ครูที่ปรึกษาที่เกี่ยวข้อง และหัวหน้าคณะครูที่ปรึกษาสภานักเรียนรับทราบ","body":"ให้มีการประชุมส่งมอบงานอย่างเป็นทางการ และจัดทำบันทึกส่งมอบโดยมีผู้ส่งมอบ ผู้รับมอบ ครูที่ปรึกษาที่เกี่ยวข้อง และหัวหน้าคณะครูที่ปรึกษาสภานักเรียนรับทราบ","keywords":["หมวด 16"],"sort_order":110},{"section_no":16,"clause_no":111,"title":"การเสนอแก้ไขเพิ่มเติมระเบียบนี้อาจริเริ่มโดยผู้บริหาร หัวหน้าฝ่ายปกครอง ครูที่ปรึกษาสภานักเรียน หรือคณะกรรมการสภานักเรียน และต้องเสนอผ่านกระบวนการพิจารณาของโรงเรียนก่อนประกาศใช้","body":"การเสนอแก้ไขเพิ่มเติมระเบียบนี้อาจริเริ่มโดยผู้บริหาร หัวหน้าฝ่ายปกครอง ครูที่ปรึกษาสภานักเรียน หรือคณะกรรมการสภานักเรียน และต้องเสนอผ่านกระบวนการพิจารณาของโรงเรียนก่อนประกาศใช้","keywords":["หมวด 16"],"sort_order":111},{"section_no":16,"clause_no":112,"title":"เรื่องใดที่มิได้กำหนดไว้ในระเบียบนี้ ให้หัวหน้าฝ่ายปกครองเสนอผู้บริหารโรงเรียนเพื่อวินิจฉัยหรือออกแนวปฏิบัติเพิ่มเติมตามความเหมาะสม","body":"เรื่องใดที่มิได้กำหนดไว้ในระเบียบนี้ ให้หัวหน้าฝ่ายปกครองเสนอผู้บริหารโรงเรียนเพื่อวินิจฉัยหรือออกแนวปฏิบัติเพิ่มเติมตามความเหมาะสม","keywords":["หมวด 16"],"sort_order":112},{"section_no":16,"clause_no":113,"title":"ในปีแรกที่ใช้ระเบียบนี้ ให้คณะกรรมการสภานักเรียนที่ปฏิบัติหน้าที่อยู่ยังคงปฏิบัติหน้าที่ต่อไปจนกว่าจะมีคำสั่งแต่งตั้งคณะกรรมการชุดใหม่หรือจนกว่าโรงเรียนจะมีคำสั่งเป็นอย่างอื่น","body":"ในปีแรกที่ใช้ระเบียบนี้ ให้คณะกรรมการสภานักเรียนที่ปฏิบัติหน้าที่อยู่ยังคงปฏิบัติหน้าที่ต่อไปจนกว่าจะมีคำสั่งแต่งตั้งคณะกรรมการชุดใหม่หรือจนกว่าโรงเรียนจะมีคำสั่งเป็นอย่างอื่น","keywords":["หมวด 16"],"sort_order":113}]'::jsonb) as x(section_no integer, clause_no integer, title text, body text, keywords jsonb, sort_order integer) on x.section_no = s.section_no
on conflict (version_id, clause_no) do nothing;

-- The source document places the next section heading immediately after the
-- last clause of each section. Keep that heading in the section table only.
update public.council_regulation_clauses c
set body = regexp_replace(c.body, chr(10) || 'หมวด [^' || chr(10) || ']+' || chr(10) || '[^' || chr(10) || ']+$', '')
where c.version_id = (select id from public.council_regulation_versions where regulation_key = 'azizstan_student_council' and version_label = '2569');

commit;
